// enfría un color (la tarde de invierno): f = 0 lo deja, f = 1 lo vuelve azul y oscuro
const a_frioCol = (c, f) => f <= 0 ? c : (0xff000000 | (((c >> 16 & 255) * (1 - 0.08 * f)) << 16) | (((c >> 8 & 255) * (1 - 0.3 * f)) << 8) | ((c & 255) * (1 - 0.44 * f))) >>> 0;

// pega una capa con huecos sobre el fotograma (f: la enfría al pegarla)
function a_pegar(R, b, f = 0) { const d = R.buf; if (f > 0) { for (let i = 0; i < b.length; i++) if (b[i] !== A_VACIO) d[i] = a_frioCol(b[i], f); } else for (let i = 0; i < b.length; i++) if (b[i] !== A_VACIO) d[i] = b[i]; }

// enfría todo el fotograma
function a_enfria(R, f) { if (f <= 0) return; const d = R.buf; for (let i = 0; i < d.length; i++) d[i] = a_frioCol(d[i], f); }

// mezcla dos colores (a = 0 deja c, a = 1 da d)
const a_mezcla = (c, d, a) => { const r = c & 255, g = c >> 8 & 255, b = c >> 16 & 255; return (0xff000000 | ((b + ((d >> 16 & 255) - b) * a) << 16) | ((g + ((d >> 8 & 255) - g) * a) << 8) | (r + ((d & 255) - r) * a)) >>> 0; };

// la trama ordenada de 4 × 4
const A_B4 = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5];

const a_b4 = (x, y) => (A_B4[((y & 3) << 2) | (x & 3)] + 0.5) / 16;

// rectángulo con pset (respeta R.recorte); c puede ser función (x, y) → color o null
