  rect(208, 110, 238, 111, a_P.hie1); rect(208, 110, 238, 110, a_P.hie3);
  for (let i = 0; i < 14; i++) { const x = 122 + i * 6; rect(x, 106, x + 4, 119, a_P.hie2); rect(x, 106, x + 1, 119, a_P.hie4); rect(x + 4, 106, x + 4, 119, a_P.hie0); rect(x + 1, 105, x + 3, 105, a_P.hie3); pset(x + 2, 108, a_P.hie1); pset(x + 2, 116, a_P.hie1); rect(x + 5, 108, x + 5, 117, a_P.lad0); }
  rect(121, 120, 205, 120, a_P.hie0); rect(122, 120, 124, 121, a_P.hie0); rect(202, 120, 204, 121, a_P.hie0); rect(206, 109, 208, 112, a_P.lata1); pset(207, 108, a_P.hie0); rect(120, 112, 121, 114, a_P.hie1);
  rect(118, 122, 210, 123, a_P.sue0);
  // la estantería de la izquierda, con sus cosas: tacos de madera, latas, tarros con pinceles, una radio y planos
  rect(3, 36, 51, 113, C.k); rect(4, 37, 50, 113, a_P.mad0); rect(4, 37, 6, 113, a_P.mad2); rect(48, 37, 50, 113, a_P.mad1); rect(4, 37, 50, 38, a_P.mad3);
  for (const y of [56, 75, 94, 112]) { rect(4, y, 50, y + 1, a_P.mad2); rect(4, y, 50, y, a_P.mad4); rect(7, y + 2, 47, y + 3, hex('#24160c')); }
