    R.copiar(a_capa(R, 'taller', () => a_tallerFijo(R)));
    // la luz de la ventana en el suelo (se va con el frío), con la sombra de los montantes
    if (f < 1) a_tinta(R, 70, 124, 268, 176, hex('#ffe6a8'), (x, y) => { const u = (y - 124) / 52, xa = 104 - u * 34, xb = 222 + u * 44; if (x < xa || x > xb || y > 172) return 0; const s = (x - xa) / (xb - xa) * 5, sy = (y - 124) / 16; if (Math.abs(s - Math.round(s)) < 0.045 || Math.abs(sy - Math.round(sy)) < 0.07) return 0; return (1 - f) * (0.34 - u * 0.1); });
    // con frío, el charco de luz de la bombilla
    if (f > 0.3) a_tinta(R, 150, 126, 250, 172, a_P.amb, (x, y) => { const d = ((x - 200) / 50) ** 2 + ((y - 149) / 22) ** 2; return d < 1 ? (1 - d) * 0.3 * (f - 0.3) / 0.7 * (0.94 + 0.06 * Math.sin(t * 17)) : 0; });
    a_pegar(R, a_capa(R, 'tallerMedio', () => a_tallerMedio(R), true));
    a_enfria(R, f * 0.8);
    // la ciudad por el ventanal y sus montantes de hierro, con la escarcha en cada cristal
    a_ciudad(R, t, A_VENT, f);
    for (let j = 0; j < 3; j++) for (let i = 0; i < 5; i++) a_escarcha(R, A_PX[i], A_PY[j], A_PX[i + 1] - 2, A_PY[j + 1] - 2, f, i + j * 5);
    const mo = a_frioCol(a_P.ace1, f * 0.7), ml = a_frioCol(a_P.ace3, f * 0.7);
    for (let i = 1; i < 5; i++) { rect(A_PX[i] - 1, 25, A_PX[i] - 1, 97, mo); } for (let j = 1; j < 3; j++) { rect(101, A_PY[j] - 1, 223, A_PY[j] - 1, mo); if (f < 0.6) rect(101, A_PY[j], 223, A_PY[j], null ?? ml); }
    rect(98, 22, 226, 24, mo); rect(98, 22, 100, 99, mo); rect(224, 22, 226, 99, mo); rect(98, 98, 226, 99, mo); rect(98, 22, 226, 22, ml); rect(98, 22, 98, 99, ml);
    // el reflejo del cristal de día: dos rayas diagonales muy tenues
    if (f < 0.5) for (let n = 0; n < 60; n++) { const x = 108 + n, y = 92 - n; if (y > 26 && (x - 100) % 24.6 > 2 && n % 3) { const c = R.pget(x, y); pset(x, y, a_mezcla(c, C.blanco, 0.3)); } }
    // la pestaña abatible del cristal del centro, entreabierta
    rect(150, 84, 173, 84, ml);
    // el gato en el alféizar
    a_gato(R, 132, 100, t, 1, [a_P.fuego0, a_P.ambS, a_P.amb].map((c) => a_frioCol(c, f)));
    // el aire que tiembla sobre el radiador cuando calienta
    if (f < 0.6) for (let n = 0; n < 9; n++) { const x0 = 126 + n * 9, u = ((t * 0.6 + n * 0.37) % 1); for (let i = 0; i < 6; i++) { const y = 104 - Math.round(u * 20) - i, x = x0 + Math.round(Math.sin((y + t * 14) * 0.5 + n) * 1.4); if (y > 84 && (1 - u) * (1 - f / 0.6) > 0.25 + i * 0.08) pset(x, y, a_mezcla(R.pget(x, y), C.blanco, 0.42)); } }
    else { for (let i = 0; i < 14; i++) rect(123 + i * 6, 107, 123 + i * 6, 107, hex('#8090b0')); }
    // las motas de polvo en el rayo de sol
    if (f < 0.7) for (let n = 0; n < 16; n++) { const x = Math.round(96 + h(n, 1, 25) * 150 + Math.sin(t * 0.4 + n) * 5), y = Math.round(104 + ((h(n, 2, 25) * 60 + t * (1.5 + n % 3)) % 60)); if (Math.sin(t * 2.2 + n * 1.7) > 0.2) pset(x, y, hex('#fff6d0')); }
