// dibuja una lista de trazos [{ p: [[x, y], …], c, peso, g }] hasta la fracción f (por orden; cada trazo tarda según su
// longitud × peso) y devuelve la punta: dónde va el lápiz en ese instante
function a_trazar(R, trazos, f) {
  if (trazos._L == null) { let tot = 0; for (const z of trazos) { let l = 0; for (let i = 1; i < z.p.length; i++) l += Math.hypot(z.p[i][0] - z.p[i - 1][0], z.p[i][1] - z.p[i - 1][1]); z.l = Math.max(1, l); z.d = z.l * (z.peso ?? 1); tot += z.d; } trazos._L = tot; }
  let q = Math.max(0, Math.min(1, f)) * trazos._L, punta = trazos[0].p[0];
  for (const z of trazos) { if (q <= 0) break; let resto = Math.min(1, q / z.d) * z.l; q -= z.d;
    for (let i = 1; i < z.p.length && resto > 0; i++) { const [ax, ay] = z.p[i - 1], [bx, by] = z.p[i], d = Math.hypot(bx - ax, by - ay) || 1, u = Math.min(1, resto / d), ex = ax + (bx - ax) * u, ey = ay + (by - ay) * u;
      R.linea(ax, ay, ex, ey, z.c); if (z.g) R.linea(ax, ay + 1, ex, ey + 1, z.c); punta = [Math.round(ex), Math.round(ey)]; resto -= d; } }
  return punta;
}

// el rayado de un polígono: rayas paralelas cada «paso» px (sh: su inclinación; con paso 1 es una mancha de polvo de lápiz)
function a_rayado(pol, paso, c, o = {}) {
  const sh = o.sh ?? 0.6, peso = o.peso ?? 0.3, P = pol.map(([x, y]) => [x + sh * y, y]), out = []; let a = Infinity, b = -Infinity, n = 0;
  for (const [x] of P) { a = Math.min(a, x); b = Math.max(b, x); }
  for (let cx = Math.ceil(a) + 0.5; cx < b; cx += paso, n++) { const ys = [];
    for (let i = 0; i < P.length; i++) { const [ax, ay] = P[i], [bx, by] = P[(i + 1) % P.length]; if ((ax <= cx && bx > cx) || (bx <= cx && ax > cx)) ys.push(ay + (cx - ax) / (bx - ax) * (by - ay)); }
    ys.sort((u, v) => u - v);
    for (let k = 0; k + 1 < ys.length; k += 2) { const s = [[cx - sh * ys[k], ys[k]], [cx - sh * ys[k + 1], ys[k + 1]]]; out.push({ p: n & 1 ? s.reverse() : s, c, peso }); } }
  return out;
}

const a_linea = (c, ...p) => ({ p, c });

const a_cerrado = (c, p) => ({ p: [...p, p[0]], c });

