// copia ampliada y desenfocada de un trozo [sx, sy, sw, sh] de una capa: el fondo de una cámara de cerca
function a_borroso(R, src, [sx, sy, sw, sh], vela, a) {
  const tmp = new Uint32Array(320 * 180);
  for (let y = 0; y < 180; y++) for (let x = 0; x < 320; x++) tmp[y * 320 + x] = src[Math.min(179, Math.floor(sy + y * sh / 180)) * 320 + Math.min(319, Math.floor(sx + x * sw / 320))];
  for (let y = 0; y < 180; y++) for (let x = 0; x < 320; x++) { let r = 0, g = 0, b = 0, n = 0; for (let j = -3; j <= 3; j += 1.5) for (let i = -3; i <= 3; i += 1.5) { const c = tmp[Math.max(0, Math.min(179, Math.round(y + j))) * 320 + Math.max(0, Math.min(319, Math.round(x + i)))]; r += c & 255; g += c >> 8 & 255; b += c >> 16 & 255; n++; }
    R.pset(x, y, a_mezcla((0xff000000 | ((b / n) << 16) | ((g / n) << 8) | (r / n)) >>> 0, vela, a)); }
}

