// una nube pequeña de tres tonos, con pset (se recorta a su ventana)
function b_nube(R, cx, cy, w, cols, k = 0) {
  for (let i = -w; i <= w; i++) { const e = Math.sqrt(1 - (i / w) * (i / w)), top = Math.round(e * (3 + 2.4 * h(i >> 2, k, 5)) + (h(i >> 1, k, 6) > 0.6 ? 1 : 0));
    for (let j = -top; j <= 1; j++) R.pset(Math.round(cx) + i, cy + j, j <= -top + 1 ? cols[2] : j >= 0 ? cols[0] : cols[1]); }
}

