  rect(x0 + 40, y0 + 16, x1 - 40, 169, hex('#2a1a10')); b_zona(R, x0 + 41, y0 + 17, x1 - 41, 169, (x, y) => ((x + y) % 5 === 0 ? hex('#3a2616') : null));
