    R.disco(x0 + w - 12, y0 + 10, 5, b_G[8]); const bx = x0 + 22, by = y0 + a - 26;
    R.poligono([[bx - 10, by], [bx + 14, by], [bx + 10, by + 6], [bx - 6, by + 6]], b_G[1]); R.rect(bx - 9, by, bx + 13, by, b_G[4]); R.rect(bx + 1, by - 22, bx + 1, by, b_G[0]);
    R.poligono([[bx + 3, by - 21], [bx + 15, by - 3], [bx + 3, by - 3]], b_G[8]); R.poligono([[bx - 1, by - 18], [bx - 10, by - 3], [bx - 1, by - 3]], b_G[6]); R.linea(bx + 3, by - 21, bx + 15, by - 3, b_G[3]);
    for (let i = 0; i < 9; i++) { R.pset(bx - 8 + i * 3, by + 9 + (i % 2), b_G[7]); R.pset(bx - 6 + i * 3, by + 12, b_G[5]); }
    for (const [cx, cy] of [[x0 + 8, y0 + 9], [x0 + 26, y0 + 6]]) for (let i = -5; i <= 5; i++) { R.pset(cx + i, cy, b_G[8]); if (Math.abs(i) < 3) R.pset(cx + i, cy - 1, b_G[8]); R.pset(cx + i, cy + 1, b_G[6]); }
