    for (let x = x0; x < x0 + w; x += 5) { R.rect(x + 1, y0 + a - 24, x + 3, y0 + a - 12, b_G[4]); R.pset(x + 2, y0 + a - 25, b_G[4]); R.rect(x + 3, y0 + a - 24, x + 3, y0 + a - 12, b_G[2]); } R.rect(x0, y0 + a - 20, x0 + w - 1, y0 + a - 20, b_G[3]);
