    R.rect(x0 - 5, top + 27, x1 + 5, top + 29, c_P.piano3); R.rect(x0 - 5, top + 27, x1 + 5, top + 27, c_P.piano4);
    R.rect(x0 + 5, top + 30, x1 - 5, top + 46, c_P.marfil); R.rect(x0 + 5, top + 44, x1 - 5, top + 46, c_P.marfilS); R.rect(x0 + 5, top + 47, x1 - 5, top + 47, c_P.k);
