// el letrero sobre el ladrillo, fotograma a fotograma: la pintura deja ver las juntas y algún desconchón. o.letrero
// cuánto hay pintado (de izquierda a derecha), o.lavable aguado y pálido, o.lavado la franja ya borrada (desde la
// izquierda) con el agua que chorrea, o.buena lo repasado con pintura fuerte y brillante (desde la izquierda)
function d_letreroPinta(R, t, o) {
  const B = R.buf, sig = d_capa(R, 'ke-letrero', () => d_letreroFijo(R)), [x0, y0, x1, y1] = d_LET, W = x1 - x0 + 1;
  const let_ = Math.max(0, Math.min(1, o.letrero ?? 1)), lav = Math.max(0, Math.min(1, o.lavado ?? 0)), bue = Math.max(0, Math.min(1, o.buena ?? 0));
  const xP = x0 + let_ * (W + 8) - 4, xL = x0 + lav * (W + 8) - 4, xB = x0 + bue * (W + 8) - 4, palido = hex('#f2ece0'), agua = hex('#cfe2ee');
  for (let y = y0; y <= y1; y++) { const mella = Math.round(h(0, y >> 1, 81) * 5 - 2 + Math.sin(y * 0.9) * 1.5);
    for (let x = x0; x <= x1; x++) { const i = y * 320 + x, s = sig[i]; if (!s) continue; if (let_ < 1 && x > xP + mella) continue; const base = B[i], junta = d_esJunta(base), g = h(x, y, 82);
      if (bue > 0 && x <= xB + mella) { B[i] = g < 0.012 ? base : d_mez(s, base, junta ? 0.2 : 0.05); if (x > xB + mella - 2 && bue < 1) B[i] = d_mez(B[i], palido, 0.5); else if (g > 0.975 && Math.sin(t * 4 + x * 0.7 + y) > 0.2) B[i] = d_mez(B[i], palido, 0.55); continue; }
      if (lav > 0 && x <= xL + mella) { B[i] = d_mez(d_mez(base, s, g < 0.3 ? 0.2 : 0.08), agua, 0.14); continue; }
      if (d_ruido(x, y, 5, 83) > 0.86 && g > 0.3) continue;   // desconchones
      if (o.lavable) B[i] = d_mez(d_mez(s, palido, 0.22), base, junta ? 0.5 : 0.2 + (g < 0.3 ? 0.14 : 0));
      else B[i] = d_mez(s, base, junta ? 0.42 : 0.14 + (g < 0.2 ? 0.1 : 0));
      if (let_ < 1 && x > xP + mella - 2) B[i] = d_mez(B[i], palido, 0.45);   // el filo fresco de la brocha
    } }
  // el agua que chorrea de lo lavado, muro abajo hasta la acera
  if (lav > 0 && bue < lav) for (let k = 0; k < 14; k++) { const x = Math.round(x0 + 3 + h(k, 1, 84) * (W - 6)); if (x > xL || x <= xB) continue; const v = 16 + h(k, 2, 84) * 14, y = y1 - 20 + ((t * v + h(k, 3, 84) * 60) % 44), n = 5 + (k % 4);
    for (let j = 0; j < n; j++) if (y - j > y0 + 20 && y - j < 150) d_os(R, x, y - j, j === 0 ? 0.6 : 0.3, agua); if (y > 140) { d_os(R, x - 1, 150, 0.4, agua); d_os(R, x + 1, 150, 0.4, agua); } }
  return { xP: Math.round(Math.min(x1, Math.max(x0, xP))), xL: Math.round(Math.min(x1, Math.max(x0, xL))), xB: Math.round(Math.min(x1, Math.max(x0, xB))) };
}

// dónde va el andamio colgante: o.andamio = true | y | [y] | [x, y] (y = el tablón, donde pisa el pintor)
function d_andamioGeo(o) {
  const a = o.andamio; if (a == null || a === false) return null;
  const [lx0, , lx1] = d_LET, f = (v) => lx0 + Math.max(0, Math.min(1, v)) * (lx1 - lx0 + 9) - 4, xdef = Math.max(96, Math.min(214, o.buena ? f(o.buena) : o.lavado ? f(o.lavado) : f(o.letrero ?? 1)));
  const y = typeof a === 'number' ? a : Array.isArray(a) ? (a.length > 1 ? a[1] : a[0]) : 112, x = Array.isArray(a) && a.length > 1 ? a[0] : xdef;
  return { x: Math.round(Math.max(52, Math.min(250, x))), y: Math.round(y ?? 112), w: 36 };
}

// 'pared', cámara general: copia la capa, pinta el letrero según las opciones y anima la vida del muro
function d_pared(R, t, o = {}) {
  R.copiar(d_capa(R, 'ke-pared', () => d_paredFija(R)));
  // la bocacalle: nubes, la copa del arce que tiembla, paseantes diminutos y un perro
  d_nubes(R, t, { n: 5, s: 0.62, y0: 52, y1: 84, x0: 271, x1: 319, veda: (x, y) => x < 271 || y > 100 || y < 49 });
  for (let k = 0; k < 9; k++) if (Math.sin(t * 2.6 + k * 1.9) > 0.3) { const a = h(k, 1, 91) * 6.28, d = 4 + h(k, 2, 91) * 10; R.pset(284 + Math.cos(a) * d, 104 + Math.sin(a) * d, k % 2 ? hex('#f6c858') : hex('#b84e22')); }
  R.recorte([271, 110, 319, 150]);
  { const u = (t * 6) % 110, x = 262 + u; d_figurin(R, x, 150, t, { c: hex('#c84a3a'), pelo: hex('#e8c060') }); const xd = x + 8, m = Math.floor(t * 6) & 1; d_rc(R, xd, 147, xd + 4, 148, hex('#f2f2ee')); R.pset(xd + 5, 146, hex('#f2f2ee')); R.pset(xd + 5, 147, hex('#f2f2ee')); R.pset(xd - 1, 146, hex('#f2f2ee')); R.pset(xd + (m ? 0 : 1), 149, hex('#c8c8c4')); R.pset(xd + (m ? 4 : 3), 149, hex('#c8c8c4')); R.linea(x + 2, 146, xd + 4, 146, hex('#6a3a2a'));
    const x2 = 330 - ((t * 5 + 40) % 130); d_figurin(R, x2, 150, t + 1, { c: hex('#3a6a5a'), pelo: hex('#5a3a22'), dir: -1 }); }
  R.recorte(null);
  R.rect(283, 130, 285, 150, hex('#4e3626'));
  const geo = d_letreroPinta(R, t, o), an = d_andamioGeo(o);
  // vida del muro: palomas en la barandilla, el gato de la ventana, la cortina, la gota de la bajante, hierbajos, hojas
  d_paloma(R, 22, 43, t, 0); d_paloma(R, 31, 43, t, 1, -1);
  { const u = (t % 9) / 9, x = u < 0.55 ? 46 : 46 + (u - 0.55) * 220, y = u < 0.55 ? 43 : 43 - Math.sin((u - 0.55) / 0.45 * Math.PI) * 30 - (u - 0.55) * 60; if (u < 0.55) d_paloma(R, 46, 43, t, 2); else if (y > 20 || x > 180) { const al = Math.floor(t * 9) & 1; d_rc(R, x - 2, y, x + 1, y + 1, hex('#8a8e9c')); R.pset(x + 2, y, hex('#5e6270')); R.pset(x - 1, y + (al ? -1 : 2), hex('#c8ccd8')); R.pset(x, y + (al ? -2 : 2), hex('#c8ccd8')); } }
  { const k = hex('#2a2428'), cx = 26, cy = 112; R.rect(cx - 2, cy - 4, cx + 2, cy - 1, k); R.rect(cx - 1, cy - 7, cx + 2, cy - 5, k); R.pset(cx - 1, cy - 8, k); R.pset(cx + 2, cy - 8, k); R.pset(cx, cy - 6, hex('#e8d040')); R.pset(cx + 2, cy - 6, hex('#e8d040')); const a = Math.sin(t * 1.6); R.pset(cx - 3, cy - 1, k); R.pset(cx - 4, cy - 2 - Math.round(a), k); R.pset(cx - 5, cy - 3 - Math.round(a * 2), k); }
  { const f = Math.round(Math.sin(t * 1.3) * 1.2); for (let x = 18; x <= 38; x += 2) R.pset(x, 37 + ((x >> 1) & 1 ? f : 0), hex('#cfc4a4')); }
  { const u = (t * 0.75) % 1, y = 147 + u * u * 6; if (u < 0.8) R.pset(68, y, hex('#cfe2ee')); else { R.pset(66, 153, hex('#e8f2f8')); R.pset(70, 153, hex('#e8f2f8')); } R.rect(65, 154, 71, 154, hex('#9aa6b0')); R.pset(67, 154, hex('#d8e6ee')); }
  for (let k = 0; k < 7; k++) { const x = Math.round(84 + h(k, 1, 92) * 170), m = Math.round(Math.sin(t * 2 + k * 1.3)); R.pset(x + m, 146, hex('#5aa83a')); R.pset(x + m, 147, hex('#3a7a28')); R.pset(x, 148, hex('#3a7a28')); R.pset(x + 2 - m, 147, hex('#8ad05a')); }
  d_hojas(R, t, 9, 0, 320, 18, 150, 93); d_hojasSuelo(R, t, 7, 153, 178, 94);
  // el andamio: su sombra en el muro y la barandilla de detrás (lo demás, en keeneDelante)
  if (an) { const { x, y, w } = an; for (let yy = y + 6; yy <= y + 10; yy++) for (let xx = x - w + 5; xx <= x + w + 7; xx++) d_os(R, xx, yy, 0.3); for (let yy = y - 9; yy <= y + 6; yy += 1) { d_os(R, x - w + 5, yy, 0.25); d_os(R, x + w + 5, yy, 0.25); }
    R.rect(x - w, y - 12, x + w, y - 12, hex('#6a6e7c')); R.rect(x - w, y - 6, x + w, y - 6, hex('#555866')); for (let xx = x - w + 12; xx < x + w; xx += 12) R.rect(xx, y - 12, xx, y - 1, hex('#555866')); }
  return { suelo: 160, letrero: d_LET.slice(), zapato: [153, 84], xPinta: geo.xP, xLava: geo.xL, xBuena: geo.xB, andamio: an && { x: an.x, y: an.y, x0: an.x - an.w + 5, x1: an.x + an.w - 5 }, escalera: [5, 56, 55, 116], libre: [70, 152, 268, 165] };
}

// lo de delante del andamio: el tablón, los estribos, la barandilla de delante, las cuerdas con sus poleas y un bote
// colgado; se pinta después del pintor
function d_paredDelante(R, t, o = {}) {
  const an = d_andamioGeo(o); if (!an) return {};
  const { x, y, w } = an, fe = hex('#3a3c48'), feL = hex('#8a8e9c'), cu = hex('#b8985e'), cuS = hex('#7a6238');
  for (const ex of [x - w, x + w]) { R.rect(ex - 2, 21, ex + 2, 22, fe); R.pset(ex, 23, feL); for (let yy = 24; yy < y - 16; yy++) { R.pset(ex, yy, (yy + (ex & 1)) % 3 ? cu : cuS); if (yy > y - 60 && yy % 3 === 0) R.pset(ex + 1, yy, cuS); }
    R.rect(ex - 2, y - 19, ex + 2, y - 15, fe); R.pset(ex, y - 17, feL); R.rect(ex - 1, y - 14, ex + 1, y + 5, fe); R.rect(ex, y - 14, ex, y + 4, feL); R.rect(ex - 3, y + 4, ex + 3, y + 5, fe); }
  R.rect(x - w, y - 10, x + w, y - 10, feL); R.rect(x - w, y - 9, x + w, y - 9, fe);
  R.rect(x - w - 3, y + 1, x + w + 3, y + 4, hex('#a8743c')); R.rect(x - w - 3, y + 1, x + w + 3, y + 1, hex('#d8a868')); R.rect(x - w - 3, y + 4, x + w + 3, y + 4, hex('#5e3a1e')); for (let xx = x - w + 4; xx < x + w; xx += 11) R.rect(xx, y + 2, xx, y + 3, hex('#83552c'));
  R.rect(x - w - 3, y - 1, x + w + 3, y, hex('#83552c')); R.rect(x - w - 3, y - 1, x + w + 3, y - 1, hex('#b88648'));
  { const bx = x + w - 9, by = y + 5 + 9; R.linea(bx, y + 5, bx - 3, by - 6, fe); R.linea(bx, y + 5, bx + 3, by - 6, fe); R.rect(bx - 4, by - 6, bx + 4, by, hex('#c8ccd4')); R.rect(bx + 2, by - 6, bx + 4, by, hex('#8a8e9c')); R.rect(bx - 4, by - 6, bx + 4, by - 5, d_PIN.rojo); R.pset(bx - 3, by - 3, hex('#ffffff')); R.pset(bx - 4, by - 2, d_PIN.rojo); R.pset(bx - 4, by - 1, d_PIN.rojo); }
  return { andamio: { x, y } };
}

const d_VELAS = [[150, 124], [172, 126], [128, 127], [196, 124], [110, 124], [214, 128], [160, 132], [184, 133], [138, 133], [232, 125], [92, 128], [205, 134]];

const d_OFRENDAS = [['ramo', 122, 122, 1], ['nota', 142, 94], ['ramo', 222, 123, -1], ['dibujo', 176, 92], ['nota', 204, 97], ['ramo', 166, 121, 1], ['nota', 112, 97], ['ramo', 86, 124, -1], ['nota', 232, 93], ['dibujo', 78, 93], ['ramo', 244, 126, 1], ['nota', 158, 97], ['flor', 136, 138], ['flor', 190, 139], ['nota', 126, 90], ['flor', 104, 136]];

// la capa fija del 'pie' (de día): el muro de cerca con el borde del letrero, el zócalo, la acera y la farola
function d_pieFija(R) {
  const px = (x, y, c) => d_px(R, x, y, c), P = d_PIN, OSC = hex('#3a2228'), MUS = hex('#5a6a3a');
  // el muro, de cerca: ladrillos de 16 × 8 con sus cantos, y encima la parte de abajo del letrero
  for (let y = 0; y < 104; y++) for (let x = 0; x < 320; x++) { let c = d_ladrillo(x, y, 2, 16, 8); const hum = Math.max(0, (y - 74) / 34) * 0.7 + Math.max(0, d_ruido(x, y, 30, 33) - 0.6) * 2;
    if (hum > d_b4(x, y)) c = d_mez(c, OSC, 0.28); if (d_ruido(x, y, 14, 47) > 0.8 && h(x, y, 48) > 0.5) c = d_mez(c, hex('#e8dcd0'), 0.3); if (y > 92 && h(x >> 1, y, 49) < (y - 90) / 22) c = d_mez(c, MUS, 0.4);
    px(x, y, c); }
  { const sig = R.nuevo(), prev = R.usar(sig), YB = 76;
    // el letrero sigue a izquierda y derecha fuera de cuadro: bajo la barra del año solo queda el cuero negro
    R.rect(0, 0, 319, YB, P.rojo); R.rect(0, 0, 319, YB - 6, P.crema); for (let x = 0; x < 320; x++) R.pset(x, YB - 12, P.oro);
    for (let x = 4; x <= 316; x += 2) R.pset(x, 58, P.cremaS);
    // la mitad de abajo del zapato: el cuero negro con su brillo y el pespunte, la suela con su vira y el tacón
    R.poligono([[16, 0], [190, 0], [214, 6], [238, 15], [256, 27], [264, 40], [14, 40], [13, 14]], P.negro);
    R.poligono([[214, 12], [236, 21], [250, 33], [232, 25]], P.brillo); R.poligono([[18, 18], [21, 18], [20, 36], [17, 36]], P.brillo); R.poligono([[120, 18], [160, 24], [160, 27], [120, 21]], P.brillo);
    for (let k = 16; k < 40; k += 2) { R.pset(196 - k * 0.2 - Math.sin(k / 13) * 6, k, P.pesp); R.pset(197 - k * 0.2 - Math.sin(k / 13) * 6, k, P.pesp); R.pset(52 + k * 0.2, k, P.pesp); }
    R.poligono([[12, 40], [266, 40], [270, 45], [264, 52], [70, 52], [66, 62], [16, 62], [12, 52]], P.suela); R.rect(12, 40, 266, 43, P.suelaL); R.rect(16, 59, 66, 62, d_mez(P.suela, d_K, 0.4)); for (let x = 16; x < 264; x += 5) R.pset(x, 42, P.suela);
    for (const ax of [286, 302]) { R.poligono([[ax, 42], [ax + 5, 49], [ax, 56], [ax - 5, 49]], P.rojo); R.poligono([[ax, 46], [ax + 2, 49], [ax, 52], [ax - 2, 49]], P.oro); }
    R.usar(prev); const B = R.buf;
    for (let y = 0; y <= YB; y++) for (let x = 0; x < 320; x++) { const i = y * 320 + x, s = sig[i]; if (!s || (d_ruido(x, y, 7, 85) > 0.86 && h(x, y, 87) > 0.3 && !(y < 16 && x < 180))) continue; const base = B[i]; B[i] = d_mez(s, base, d_esJunta(base) ? 0.36 : 0.1 + (h(x, y, 86) < 0.2 ? 0.1 : 0)); } }
  // el zócalo de granito con su repisa
  for (let y = 104; y < 118; y++) for (let x = 0; x < 320; x++) { const g = h(x, y, 51); let c = y === 104 ? hex('#e2dcd2') : y === 105 ? hex('#cfc9be') : y === 106 ? hex('#8e8880') : g < 0.15 ? hex('#9a948c') : g > 0.88 ? hex('#cac4ba') : hex('#b4aea6'); if ((x + 11) % 54 === 0 && y > 106) c = hex('#847e78'); if (y > 111 && h(x >> 1, y, 52) < 0.3) c = d_mez(c, MUS, 0.45); if (y === 117) c = d_mez(c, d_K, 0.4); px(x, y, c); }
  // la bajante, a la izquierda
  { const co = hex('#4e7c6a'), coL = hex('#7aa890'), coS = hex('#2e5446'); for (let y = 0; y < 108; y++) { for (let x = 13; x < 16; x++) d_os(R, x, y + 3, 0.28); px(6, y, coL); px(7, y, coL); R.rect(8, y, 10, y, co); px(11, y, coS); px(12, y, coS); if (y % 44 === 30) { R.rect(4, y, 14, y + 2, coS); R.rect(4, y, 14, y, co); } } R.rect(6, 108, 22, 113, co); R.rect(6, 108, 22, 108, coL); R.rect(6, 112, 22, 113, coS); }
  // la acera de losas (con juntas en fuga, grietas y una rejilla), el bordillo y el asfalto
  const AC = ['#b9b5b0', '#cbc7c0', '#a29e9a', '#8c8884'].map(hex), AS = ['#4c4a56', '#3e3c48', '#646270'].map(hex);
  for (let y = 118; y < 180; y++) for (let x = 0; x < 320; x++) { const g = h(x, y, 71); let c;
    if (y < 160) { c = g < 0.12 ? AC[2] : g > 0.9 ? AC[1] : AC[0]; if (d_ruido(x, y * 2, 18, 72) > 0.64 && g > 0.35) c = AC[2]; const xj = x + (x - 160) * (y - 118) * 0.008; if (Math.floor(xj + 1000) % 62 === 0 || ((y === 131 || y === 146) && x % 11 !== 0)) c = AC[3]; else if (Math.floor(xj + 999) % 62 === 0 || y === 132 || y === 147) c = d_mez(c, hex('#ffffff'), 0.12); if (y < 121) c = d_mez(c, d_K, y === 118 ? 0.4 : 0.18); }
    else if (y < 165) c = y < 162 ? hex('#dedad2') : y < 164 ? hex('#b4b0aa') : hex('#2a2832');
    else { c = g < 0.14 ? AS[1] : g > 0.93 ? AS[2] : AS[0]; if (d_ruido(x, y * 3, 20, 77) > 0.7) c = d_mez(c, hex('#8a8ea0'), 0.25); }
    px(x, y, c); }
  for (let k = 0; k < 8; k++) { let x = 30 + h(k, 1, 73) * 270, y = 122 + h(k, 2, 73) * 14; for (let i = 0; i < 16; i++) { px(x, y, AC[3]); x += h(k, i, 74) < 0.5 ? 1 : -1; y++; if (y > 158) break; } }
  R.rect(40, 150, 62, 157, hex('#3a3840')); for (let x = 42; x < 62; x += 3) R.rect(x, 151, x, 156, hex('#16141c')); R.rect(40, 150, 62, 150, hex('#6a6870'));
  for (let k = 0; k < 38; k++) { const x = h(k, 1, 76) * 320, y = h(k, 2, 76) < 0.5 ? 119 + h(k, 3, 76) * 5 : 152 + h(k, 3, 76) * 22; px(x, y, d_HOJA[k % 4]); px(x + 1, y, d_HOJA[(k + 1) % 4]); if (k % 3 === 0) px(x, y - 1, d_HOJA[k % 4]); }
  for (let k = 0; k < 12; k++) { const x = 26 + h(k, 1, 57) * 280; px(x, 117, hex('#3a7a28')); px(x + 1, 116, hex('#5aa83a')); px(x - 1, 117, hex('#5aa83a')); px(x + 1, 115, hex('#3a7a28')); }
  // la farola de fundición (el farol queda bajo la esquina de Atom)
  { const f = hex('#26282e'), fL = hex('#565a66'), X = 298; for (let x = X - 8; x < X + 12; x++) for (let y = 140; y < 143; y++) d_os(R, x + 3, y + 1, 0.3);
    R.rect(X - 1, 68, X + 1, 138, f); R.rect(X - 1, 68, X - 1, 138, fL); R.rect(X - 3, 132, X + 3, 140, f); R.rect(X - 5, 139, X + 5, 141, f); R.rect(X - 3, 132, X - 3, 138, fL); R.rect(X - 2, 96, X + 2, 97, f); R.rect(X - 2, 120, X + 2, 121, f);
    R.rect(X - 6, 66, X + 6, 67, f); R.poligono([[X - 5, 66], [X + 6, 66], [X + 4, 52], [X - 3, 52]], hex('#f6e2a0')); R.rect(X - 4, 50, X + 4, 51, f); R.poligono([[X - 4, 50], [X + 5, 50], [X + 1, 46], [X, 46]], f); R.rect(X, 52, X, 65, f); R.rect(X - 5, 52, X - 5, 66, f); R.rect(X + 5, 52, X + 5, 66, f); R.rect(X - 2, 57, X + 2, 62, hex('#fffbe0')); }
}

// una nota doblada pegada con cinta (rayas), un dibujo infantil (un sol y un corazón) y una flor suelta
function d_ofrenda(R, tipo, x, y, dir, t, k) {
  if (tipo === 'ramo') { PIEZAS_JM.ramo && PIEZAS_JM.ramo(R, x, y, { dir }); return; }
  if (tipo === 'nota') { const c = [hex('#f6f0dc'), hex('#f8e8a0'), hex('#dfeaf6')][k % 3], al = Math.sin(t * 1.4 + k) > 0.7 ? 1 : 0; R.rect(x - 4, y - 6, x + 4, y + 5, hex('#3a2a2a')); R.rect(x - 4, y - 6, x + 3, y + 4, c); R.rect(x + 2 - al, y + 3 - al, x + 3, y + 4, d_mez(c, d_K, 0.3)); for (let j = -4; j <= 1; j += 2) R.rect(x - 2, y + j, x + (j === 1 ? -1 : 1 + (k + j & 1)), y + j, hex('#5a5a7a')); R.rect(x - 2, y - 8, x + 1, y - 6, hex('#e8e0b0')); R.pset(x - 2, y - 8, hex('#c8c090')); return; }
  if (tipo === 'dibujo') { R.rect(x - 7, y - 7, x + 7, y + 6, hex('#3a2a2a')); R.rect(x - 7, y - 7, x + 6, y + 5, hex('#fbf8ee')); R.disco(x - 3, y - 3, 2.2, hex('#f4c030')); R.pset(x - 6, y - 3, hex('#f4c030')); R.pset(x - 3, y - 6, hex('#f4c030')); R.pset(x, y - 3, hex('#f4c030'));
    const r = hex('#d8303a'); R.rect(x + 1, y - 1, x + 2, y, r); R.rect(x + 4, y - 1, x + 5, y, r); R.rect(x + 1, y, x + 5, y + 1, r); R.rect(x + 2, y + 2, x + 4, y + 2, r); R.pset(x + 3, y + 3, r); for (let i = -5; i <= 4; i++) R.pset(x + i, y + 4, i % 3 ? hex('#3aa85a') : hex('#2a7a40')); R.rect(x - 1, y - 9, x + 1, y - 7, hex('#e8e0b0')); return; }
  const c = [hex('#e87a9a'), hex('#f4c030'), hex('#f2f2ee')][k % 3]; R.rect(x - 5, y, x, y, hex('#3a8a4a')); R.pset(x - 3, y - 1, hex('#5aaa5a')); R.rect(x + 1, y - 1, x + 3, y + 1, c); R.pset(x + 2, y, hex('#f08a2a'));
}

// 'pared', cámara 'pie': las ofrendas, la noche (un solo recorrido que enfría todo y deja la luz cálida) y las velas
function d_pie(R, t, o = {}) {
  const dia = !!o.dia, B = R.buf, nv = Math.max(0, Math.min(12, Math.round(o.velas ?? 0))), nf = Math.round(Math.max(0, Math.min(1, o.flores ?? 0)) * d_OFRENDAS.length);
  R.copiar(d_capa(R, 'ke-pie', () => d_pieFija(R)));
  // las notas y los dibujos pegados al muro y los ramos apoyados en el zócalo
  for (let k = 0; k < nf; k++) { const [tipo, x, y, dir] = d_OFRENDAS[k]; if (tipo === 'ramo') for (let i = -7; i <= 7; i++) d_os(R, x + i + 2, y + 1, 0.25); d_ofrenda(R, tipo, x, y, dir, t, k); }
  if (dia) { d_paloma(R, 252, 104, t, 3, -1); d_paloma(R, 40, 148, t, 5); d_hojas(R, t, 8, 0, 320, 0, 150, 95); }
  else {
    // la noche: todo se enfría y oscurece, salvo donde llega la luz del farol o la de cada vela (que tiembla)
    const L = []; for (let k = 0; k < nv; k++) { const [x, y] = d_VELAS[k]; L.push([x, y - 13, 0.75 + 0.25 * Math.sin(t * (7 + (k % 3) * 2.3) + k * 1.9) * Math.sin(t * 3.1 + k)]); }
    const coche = ((t + 3) % 11) / 2.4, xc = coche < 1 ? 380 - coche * 460 : -999;
    for (let y = 0; y < 180; y++) for (let x = 0; x < 320; x++) { const i = y * 320 + x, c = B[i]; let a = 0;
      { const dx = x - 298, dy = (y - 60) * (y > 60 ? 0.62 : 1.5), d2 = dx * dx + dy * dy; if (d2 < 9000) a += 1.1 / (1 + d2 / 520); if (y > 118) { const ex = (x - 290) / 60, ey = (y - 144) / 16, e = ex * ex + ey * ey; if (e < 1) a += (1 - e) * 0.45; } }
      if (nv && y > 40 && y < 166) for (let k = 0; k < nv; k++) { const dx = x - L[k][0], dy = (y - L[k][1]) * (y > 118 ? 1.5 : 1), d2 = dx * dx + dy * dy; if (d2 < 2600) a += L[k][2] * 0.95 / (1 + d2 / 150); }
      if (y > 164 && xc > -100) { const d = Math.abs(x - xc); if (d < 46) a += (1 - d / 46) * 0.5; }
      if (y < 46 && x > 262) a = Math.min(a, 0.2);
      const q = Math.min(1, Math.floor(Math.min(1, a) * 5 + d_b4(x, y)) / 5), r = c & 255, g = (c >>> 8) & 255, b = (c >>> 16) & 255;
      const nr = r * 0.2 + 6, ng = g * 0.25 + 9, nb = b * 0.4 + 30, wr = Math.min(255, r * 1.02 + 10), wg = g * 0.88 + 4, wb = b * 0.64;
      B[i] = (0xff000000 | ((nb + (wb - nb) * q) << 16) | ((ng + (wg - ng) * q) << 8) | (nr + (wr - nr) * q)) >>> 0; }
    // el farol encendido y sus polillas
    R.rect(296, 57, 300, 62, hex('#fffbe0')); R.rect(294, 54, 302, 64, hex('#f8e4a0')); R.rect(296, 56, 300, 62, hex('#fffbe0')); R.rect(293, 52, 293, 66, hex('#26282e')); R.rect(303, 52, 303, 66, hex('#26282e')); R.rect(298, 52, 298, 65, hex('#8a7a4a'));
    for (let k = 0; k < 3; k++) { const a = t * (2.2 + k * 0.7) + k * 2, x = 298 + Math.cos(a) * (9 + k * 3), y = 60 + Math.sin(a * 1.3) * (6 + k * 2); if (y > 47) R.pset(x, y, hex('#f6f0d0')); }
    d_hojasSuelo(R, t, 4, 150, 176, 96);
  }
  // las velas (la llama y su cerco claro)
  for (let k = 0; k < nv; k++) { const [x, y] = d_VELAS[k]; if (!dia) for (let j = -3; j <= 3; j++) for (let i = -3; i <= 3; i++) if (Math.abs(i) + Math.abs(j) < 4 + (Math.sin(t * 9 + k) > 0 ? 1 : 0) && d_b4(x + i, y + j) < 0.5) d_os(R, x + i, y - 14 + j, 0.5, hex('#ffe9a0'));
    for (let i = -3; i <= 3; i++) d_os(R, x + i + 1, y + 1, 0.3); PIEZAS_JM.vela && PIEZAS_JM.vela(R, x, y, { t: t + k * 0.37 }); }
  return { suelo: 152, velas: d_VELAS.slice(0, nv), ofrendas: d_OFRENDAS.slice(0, nf).map(([q, x, y]) => [x, y]), farola: [298, 140], zocalo: 104, pieMuro: 118, libre: [30, 136, 280, 158] };
}

// vuelca una capa sobre el búfer en uso: lo que en la capa vale 0 deja ver lo de detrás (el cielo con sus nubes)
function d_sobre(R, capa) { const B = R.buf; for (let i = 0; i < 57600; i++) { const c = capa[i]; if (c) B[i] = c; } }

// el cielo de día (degradado tramado hasta hor), en su capa
const d_cieloDia = (R, hor) => d_capa(R, 'ke-cielo-' + hor, () => d_degradado(R, 0, 319, [[0, hex('#3f8fdc')], [Math.round(hor * 0.34), hex('#62aeec')], [Math.round(hor * 0.66), hex('#96cdf4')], [hor, hex('#dfe9d6')], [180, hex('#dfe9d6')]]));

// los cuatro tonos de la piedra de cornisas, dinteles y alféizares
const d_PIE = ['#e4dccc', '#cfc7b6', '#a69e90', '#857d72'].map(hex);

// una ventana de guillotina con dintel de piedra (o arco de ladrillo), marco blanco, reflejo y alféizar con su sombra
function d_ventana(R, x, y, w, hh, o = {}) {
  const px = (a, b, c) => d_px(R, a, b, c), cr = o.luz ? hex('#f0c878') : hex('#33465e'), rf = o.luz ? hex('#fbe4a8') : hex('#5a7ea4');
  if (o.arco) { for (let i = -1; i <= w; i++) { const u = (i - (w - 1) / 2) / ((w + 1) / 2), ya = y - 3 - Math.round(2 * (1 - u * u)); px(x + i, ya, d_L.som[1]); px(x + i, ya + 1, i & 1 ? d_L.luz[2] : d_L.som[3]); for (let yy = ya + 2; yy < y; yy++) px(x + i, yy, hex('#efeadc')); } }
  else { R.rect(x - 2, y - 3, x + w + 1, y - 2, d_PIE[0]); R.rect(x - 2, y - 1, x + w + 1, y - 1, d_PIE[2]); }
  R.rect(x - 1, y - 1, x + w, y + hh, hex('#efeadc')); R.rect(x, y, x + w - 1, y + hh - 1, cr);
  for (let k = 0; k < w - 2; k++) { px(x + k + 1, y + 5 - (k >> 1), rf); if (hh > 12) px(x + k, y + hh - 2 - (k >> 1), d_mez(cr, rf, 0.5)); }
  if (o.cortina) { R.rect(x, y, x + w - 1, y + 3, hex('#e6dcc0')); for (let i = 0; i < w; i += 2) px(x + i, y + 3, hex('#b8ac8c')); }
  if (o.visillo) { for (let yy = y; yy < y + hh; yy++) { px(x, yy, hex('#e8e4ee')); if (yy % 3) px(x + 1, yy, hex('#c8c4d4')); px(x + w - 1, yy, hex('#e8e4ee')); } }
  R.rect(x - 1, y + (hh >> 1), x + w, y + (hh >> 1), hex('#efeadc')); if (w > 7) R.rect(x + (w >> 1), y, x + (w >> 1), y + hh - 1, hex('#efeadc'));
  R.rect(x - 2, y + hh + 1, x + w + 1, y + hh + 1, d_PIE[0]); for (let i = -2; i <= w + 1; i++) d_os(R, x + i, y + hh + 2, 0.35);
  if (o.maceta) { R.rect(x, y + hh - 1, x + w - 1, y + hh, hex('#7a4a2a')); for (let i = 0; i < w; i++) px(x + i, y + hh - 2 - (i & 1), i % 3 ? hex('#3a8a4a') : [hex('#e8507a'), hex('#f4c030')][i & 1]); }
  for (let yy = y; yy < y + hh; yy++) d_os(R, x + w, yy, 0.25);
}

// los toldos, los rótulos colgantes y los postes de barbero de la calle: los llena d_fachada y los anima el fotograma
const d_TOLDOS = [], d_COLGANTES = [];

// pictogramas de 9 × 6 para los rótulos (sin letras): zapato, libro, taza, tijeras, flor
const d_PICTOS = { zapatos: ['.##......', '.###.....', '.#####...', '.########', '.########', '.##..####'], libros: ['####.####', '#..#.#..#', '#..#.#..#', '#..#.#..#', '####.####', '....#....'], cafe: ['.#.#.#...', '.........', '######.#.', '######.#.', '######...', '.####....'], barbero: ['##....##.', '##...##..', '..###....', '..###....', '##...##..', '##....##.'], flores: ['.#..#..#.', '###.#.###', '.#.###.#.', '..#.#.#..', '...###...', '....#....'] };

function d_picto(R, nombre, x, y, c, s = 1) { const f = d_PICTOS[nombre]; if (f) f.forEach((fila, j) => { for (let i = 0; i < fila.length; i++) if (fila[i] === '#') for (let b = 0; b < s; b++) for (let a = 0; a < s; a++) R.pset(x + i * s + a, y + j * s + b, c); }); }
Object.assign(d_PICTOS, { dado: ['#####', '#.###', '##.##', '###.#', '#####'], nino: ['.##.', '.##.', '####', '.##.', '.##.', '#..#'], reloj: ['.###.', '#.#.#', '#.###', '#...#', '.###.'], leon: ['.#.#.#.', '#######', '##.#.##', '#######', '.##.##.', '..###..'], corazon: ['##.##', '#####', '#####', '.###.', '..#..'], mando: ['.#####.', '#.###.#', '#######', '##...##'] });

// una casa de ladrillo de tres plantas con su tienda: cornisa con dentículos, pilastras, dos plantas de ventanas, la
// imposta, el rótulo con pictograma, el toldo de rayas, el escaparate con su género y la puerta
function d_fachada(R, x0, x1, yT, E) {
  const px = (a, b, c) => d_px(R, a, b, c), W = x1 - x0 + 1, yC = yT + 8, yS = 97, hF = (yS - yC) / 2, OSC = hex('#3a2228'), B = R.buf;
  for (let y = yT; y < 122; y++) for (let x = x0; x <= x1; x++) { let c = d_ladrillo(x, y, E.k, 6, 3); if (E.tinte) c = d_mez(c, E.tinte, E.ta ?? 0.35); if (d_ruido(x, y, 16, E.k + 20) > 0.62 && d_b4(x, y) < 0.7) c = d_mez(c, OSC, 0.2); if (y > yS - 2 && y < yS + 1) c = d_mez(c, OSC, 0.3); px(x, y, c); }
  for (let y = yC; y < 122; y++) { for (const x of [x0, x0 + 1, x0 + 2]) B[y * 320 + x] = d_mez(B[y * 320 + x], hex('#f0d0b0'), (y >> 2) & 1 ? 0.3 : 0.14); B[y * 320 + x1] = d_mez(B[y * 320 + x1], d_K, 0.45); B[y * 320 + x1 - 1] = d_mez(B[y * 320 + x1 - 1], d_K, 0.2); }
  // la cornisa
  R.rect(x0, yT, x1, yT + 2, d_PIE[0]); R.rect(x0, yT, x1, yT, hex('#f6f0e2')); R.rect(x0, yT + 3, x1, yT + 3, d_PIE[2]); for (let x = x0; x <= x1; x++) { px(x, yT + 4, (x - x0) % 3 ? d_PIE[0] : d_PIE[3]); px(x, yT + 5, (x - x0) % 3 ? d_PIE[1] : d_PIE[3]); d_os(R, x, yT + 6, 0.4); d_os(R, x, yT + 7, 0.18); }
  if (E.fronton) { const cx = (x0 + x1) >> 1; R.poligono([[cx - 12, yT], [cx, yT - 7], [cx + 12, yT]], d_PIE[1]); R.linea(cx - 12, yT, cx, yT - 7, hex('#f6f0e2')); R.linea(cx, yT - 7, cx + 12, yT, d_PIE[2]); R.disco(cx + 0.5, yT - 2.5, 1.6, d_PIE[3]); }
  // las ventanas de las dos plantas y la imposta entre ellas
  for (let f = 0; f < 2; f++) { const wy = Math.round(yC + f * hF + (hF - 15) / 2) + 2; for (let k = 0; k < E.n; k++) { const wx = Math.round(x0 + (k + 0.5) * W / E.n - 4), r = h(k, f, E.k + 5); d_ventana(R, wx, wy, 9, 14, { arco: E.arco && f === 0, luz: r < 0.16, cortina: r > 0.5 && r < 0.72, visillo: r > 0.72, maceta: r > 0.88 || (f === 1 && k === 0 && E.maceta) }); } }
  { const y = Math.round(yC + hF); for (let x = x0; x <= x1; x++) { px(x, y, d_PIE[0]); d_os(R, x, y + 1, 0.3); } }
  // la tienda: rótulo, escaparate y puerta
  const fa = E.rot ?? hex('#24463a'), cr = hex('#f0e4c0');
  R.rect(x0 + 2, 96, x1 - 2, 103, fa); R.rect(x0 + 2, 96, x1 - 2, 96, d_mez(fa, cr, 0.4)); R.rect(x0 + 2, 103, x1 - 2, 103, d_K);
  { const cx = (x0 + x1) >> 1; d_picto(R, E.tienda, cx - 4, 97, cr); for (const s of [-1, 1]) { let x = cx + s * 9; for (const w of [4, 2, 5, 3]) { if (Math.abs(x + s * w - cx) > W / 2 - 6) break; R.rect(Math.min(x, x + s * (w - 1)), 99, Math.max(x, x + s * (w - 1)), 100, d_mez(cr, fa, 0.25)); x += s * (w + 2); } } }
  const dx0 = x1 - 13, dx1 = x1 - 4;
  R.rect(x0 + 3, 104, x1 - 3, 121, d_mez(fa, d_K, 0.35)); R.rect(x0 + 5, 106, dx0 - 3, 118, hex('#7a9cb8')); R.rect(x0 + 5, 106, dx0 - 3, 108, hex('#4a6a8a'));
  for (let k = 0; k < 9; k++) { px(x0 + 8 + k, 117 - k, hex('#a8c8e0')); px(x0 + 12 + k, 117 - k, hex('#98b8d4')); }
  R.rect(x0 + 5, 119, dx0 - 3, 119, cr); R.rect(x0 + 4, 120, dx0 - 2, 121, d_mez(fa, d_K, 0.15));
  { const ex0 = x0 + 6, ex1 = dx0 - 4, n = Math.floor((ex1 - ex0) / 8);
    for (let k = 0; k < n; k++) { const x = ex0 + 1 + k * 8, r = h(k, 1, E.k + 30);
      if (E.tienda === 'zapatos') { R.rect(x, 116 - (k & 1) * 2, x + 5, 118, hex('#c8a060')); const c = [hex('#1e1a1e'), hex('#7a3a22'), hex('#c8362e')][k % 3]; R.rect(x, 113 - (k & 1) * 2, x + 1, 115 - (k & 1) * 2, c); R.rect(x + 2, 114 - (k & 1) * 2, x + 5, 115 - (k & 1) * 2, c); }
      else if (E.tienda === 'libros') { for (let i = 0; i < 6; i++) R.rect(x + i, 112 + ((i * 7 + k) % 3), x + i, 118, [hex('#c8362e'), hex('#3a6ab0'), hex('#e8c040'), hex('#3a8a4a'), hex('#eee8d8'), hex('#8a3a6a')][(i + k) % 6]); }
      else if (E.tienda === 'cafe') { R.rect(x, 117, x + 5, 118, hex('#eee8d8')); R.rect(x + 1, 113, x + 4, 116, [hex('#e8a0a0'), hex('#f0d890'), hex('#c89060')][k % 3]); px(x + 2, 112, hex('#c8362e')); R.rect(x + 2, 108, x + 3, 109, hex('#f4d890')); }
      else if (E.tienda === 'flores') { R.rect(x + 1, 115, x + 4, 118, hex('#b8623c')); R.disco(x + 3, 112, 2.4, hex('#3a8a4a')); px(x + 2, 111, [hex('#e8507a'), hex('#f4c030'), hex('#f2f2ee')][k % 3]); px(x + 4, 112, [hex('#f4c030'), hex('#e8507a')][k & 1]); px(x + 3, 110, hex('#e8507a')); }
      else { R.rect(x + 1, 110, x + 4, 118, r < 0.5 ? hex('#d8e8f0') : hex('#b8623c')); R.rect(x + 2, 111, x + 3, 114, hex('#8ab0c8')); } } }
  R.rect(dx0 - 1, 104, dx1 + 1, 121, d_K); R.rect(dx0, 105, dx1, 121, E.puerta ?? hex('#7a2c24')); R.rect(dx0 + 2, 107, dx1 - 2, 114, hex('#5a7ea4')); px(dx0 + 3, 108, hex('#a8c8e0')); px(dx0 + 4, 109, hex('#a8c8e0')); R.rect(dx0 + 2, 116, dx1 - 2, 119, d_mez(E.puerta ?? hex('#7a2c24'), d_K, 0.3)); px(dx0 + 1, 114, hex('#e8c040')); px(dx0 + 1, 115, hex('#a87a18'));
  if (E.toldo) { const [c1, c2] = E.toldo, a0 = x0 + 3, a1 = dx0 - 1; for (let y = 104; y <= 109; y++) for (let x = a0 - (y - 104 > 2 ? 1 : 0); x <= a1 + (y - 104 > 2 ? 1 : 0); x++) px(x, y, d_mez(((x - a0 + 40) >> 2) & 1 ? c1 : c2, d_K, y === 104 ? 0 : (y - 104) * 0.04)); for (let x = a0 - 1; x <= a1 + 1; x++) { d_os(R, x, 111, 0.35); d_os(R, x, 112, 0.2); } d_TOLDOS.push([a0 - 1, a1 + 1, 110, c1, c2]); }
  if (E.colgante) d_COLGANTES.push([x0 + 4, 88, E.tienda, fa]);
  if (E.tienda === 'barbero') d_COLGANTES.push([dx1 + 3, 108, 'poste']);
  return [(dx0 + dx1) >> 1, 121];
}

// un coche aparcado o en marcha (40 × 15; x = su izquierda, y = donde pisan las ruedas): o.tipo 'sedan' | 'ranchera' |
// 'pickup' | 'suv' (el de 2014); o.c color; o.dir; o.anda: las ruedas giran con t
function d_coche(R, x, y, t, o = {}) {
  x = Math.round(x); const dir = o.dir ?? 1, c = o.c ?? hex('#8a2c34'), cs = d_mez(c, d_K, 0.35), cl = d_mez(c, hex('#ffffff'), 0.35), tipo = o.tipo ?? 'sedan', X = (i) => (dir > 0 ? x + i : x + 39 - i), suv = tipo === 'suv', top = suv ? -17 : tipo === 'pickup' ? -15 : -14, hom = suv ? -11 : -9;
  const P = (pts, col) => R.poligono(pts.map(([i, j]) => [X(i) + (dir > 0 ? 0 : 1), y + j]), col), rc = (a, b, c2, d, col) => d_rc(R, Math.min(X(a), X(c2)), y + b, Math.max(X(a), X(c2)), y + d, col);
  for (let i = -1; i <= 41; i++) if ((i + y) & 1 || i % 3) { const B = R.pget(x + i, y + 1); R.pset(x + i, y + 1, d_mez(B, d_K, 0.4)); }
  const cab = tipo === 'ranchera' ? [[8, hom], [12, top], [36, top], [38, hom]] : tipo === 'pickup' ? [[17, hom], [20, top], [30, top], [33, hom]] : suv ? [[5, hom], [9, top], [31, top], [36, hom]] : [[8, hom], [13, top], [27, top], [33, hom]];
  P([[-1, -2], [-1, hom + 1], [1, hom - 1], [39, hom - 1], [41, hom + 2], [41, -2]], d_K); P(cab.map(([i, j], k) => [i + (k < 2 ? -1 : 1), j + (k === 1 || k === 2 ? -1 : 0)]), d_K);
  P([[0, -3], [0, hom + 1], [2, hom], [38, hom], [40, hom + 2], [40, -3]], c); rc(0, -5, 39, -3, cs); rc(2, hom, 37, hom, cl); P(cab, c); rc(cab[1][0] + 1, top, cab[2][0] - 1, top, cl);
  { const g = hex('#9cc4e4'), gs = hex('#5a86ac'), [a, b, c3, d] = cab, m = tipo === 'pickup' ? (b[0] + c3[0]) >> 1 : 20; P([[a[0] + 2, hom], [b[0] + 1, top + 1], [m - 1, top + 1], [m - 1, hom]], g); P([[m + 1, hom], [m + 1, top + 1], [c3[0] - 1, top + 1], [d[0] - 2, hom]], gs); if (tipo === 'ranchera' || suv) rc(29, top + 1, 29, hom - 1, c); }
  if (tipo === 'ranchera') { rc(4, -8, 35, -6, hex('#a8743c')); for (let i = 5; i < 35; i += 3) R.pset(X(i), y - 7, hex('#83552c')); }
  if (tipo === 'pickup') { rc(0, hom, 16, hom, cs); rc(2, hom - 1, 15, hom - 1, d_K); }
  if (suv) { rc(10, top - 1, 30, top - 1, hex('#4a4e5a')); }
  rc(20, hom + 1, 20, -4, cs); R.pset(X(22), y + hom + 3, d_K); R.pset(X(17), y + hom + 3, d_K);
  rc(-1, -5, 0, -3, hex('#b8bcc8')); rc(39, -5, 40, -3, hex('#b8bcc8')); R.pset(X(39), y + hom + 2, hex('#fff0a0')); R.pset(X(39), y + hom + 3, hex('#f0a030')); R.pset(X(0), y + hom + 2, hex('#e83a3a')); R.pset(X(0), y + hom + 3, hex('#e83a3a'));
  for (const wx of [8, 31]) { const cx = X(wx) + (dir > 0 ? 0.5 : 0.5), r = suv ? 3.6 : 3.2; R.disco(cx, y - 3 + 0.5, r + 1, d_K); R.disco(cx, y - 2.5, r, hex('#2a2a32')); R.disco(cx, y - 2.5, 1.6, hex('#c8ccd4')); const a = o.anda ? t * 9 * dir : 0.6; R.pset(cx + Math.cos(a) * 1.2 - 0.5, y - 2.5 + Math.sin(a) * 1.2, hex('#5a5e6a')); }
}

// un arce de acera: tronco en su alcorque y copa de otoño en cuatro tonos, con hojas sueltas
function d_arce(R, x, y, r, tonos = ['#a8451f', '#d0602a', '#ea8a34', '#f6b848']) {
  const T = tonos.map(hex), tr = hex('#4e3626'); R.rect(x - 1, y - r - 4, x + 1, y, tr); d_px(R, x - 1, y - 6, hex('#6e5038')); d_px(R, x - 2, y, tr); d_px(R, x + 2, y, tr); R.linea(x, y - r, x - r * 0.5, y - r * 1.6, tr); R.linea(x, y - r, x + r * 0.5, y - r * 1.5, tr);
  const cy = y - r * 2 - 2; for (const [dx, dy, rr, k] of [[0, 0, 1, 0], [-0.08, -0.08, 0.86, 1], [-0.22, -0.26, 0.58, 2], [0.36, -0.42, 0.34, 2], [-0.4, -0.5, 0.26, 3], [0.3, 0.36, 0.34, 0], [-0.5, 0.3, 0.3, 1]]) R.disco(x + dx * r + 0.5, cy + dy * r, rr * r, T[k]);
  for (let k = 0; k < r * 4; k++) { const a = h(k, 1, x) * 6.28, d = Math.sqrt(h(k, 2, x)) * r * 0.95; d_px(R, x + Math.cos(a) * d, cy + Math.sin(a) * d, T[(k + (Math.sin(a) > 0.3 ? 0 : 2)) % 4]); }
  return [x, cy, r];
}

// una farola de fundición con su farol (y = la acera); alto por omisión 36
function d_farola(R, x, y, alto = 36, luz = false) {
  const f = hex('#26282e'), fL = hex('#565a66'); R.rect(x, y - alto + 8, x + 1, y, f); R.rect(x, y - alto + 8, x, y, fL); R.rect(x - 1, y - 4, x + 2, y, f); R.rect(x - 2, y - 1, x + 3, y, f); R.rect(x - 1, y - alto + 16, x + 2, y - alto + 16, f);
  R.rect(x - 3, y - alto + 7, x + 4, y - alto + 7, f); R.rect(x - 2, y - alto + 1, x + 3, y - alto + 6, luz ? hex('#fff2b8') : hex('#dfe8ee')); R.rect(x - 3, y - alto, x + 4, y - alto, f); R.rect(x - 1, y - alto - 2, x + 2, y - alto - 1, f); R.rect(x - 3, y - alto + 1, x - 3, y - alto + 6, f); R.rect(x + 4, y - alto + 1, x + 4, y - alto + 6, f); R.rect(x, y - alto + 1, x, y - alto + 6, luz ? hex('#fffbe0') : hex('#f8fbfd'));
}

// las cosas del rodaje: un foco de cine en su trípode (con visera y su haz tramado), una valla de caballete y un cono
function d_foco(R, x, y, t, dir = 1, alto = 34) {
  const f = hex('#2a2c34'), fL = hex('#6a6e7c'), hy = y - alto; R.linea(x, y - 10, x - 6, y, f); R.linea(x, y - 10, x + 6, y, f); R.linea(x, y - 10, x + 1, y, fL); R.rect(x, hy + 7, x, y - 10, fL); R.rect(x + 1, hy + 7, x + 1, y - 10, f);
  R.rect(x - 4, hy, x + 4, hy + 7, f); R.rect(x - 3, hy + 1, x + 3, hy + 1, fL); const cx = x + dir * 5; R.rect(Math.min(cx, cx + dir), hy, Math.max(cx, cx + dir), hy + 7, Math.sin(t * 13 + x) > -0.9 ? hex('#fff6c8') : hex('#f4d880'));
  R.linea(cx + dir, hy - 1, cx + dir * 5, hy - 4, f); R.linea(cx + dir, hy + 8, cx + dir * 5, hy + 11, f);
  for (let k = 3; k < 46; k++) { const xx = cx + dir * k, w = 4 + k * 0.42; for (let j = -w; j <= w; j++) { const yy = Math.round(hy + 3 + k * 0.45 + j); if (yy < y + 6 && d_b4(xx, yy) < 0.34 * (1 - k / 50)) d_os(R, xx, yy, 0.5, hex('#fff2b0')); } }
}

// una valla de caballete a rayas naranjas y blancas (x = su izquierda, y = el suelo)
function d_valla(R, x, y) { const n = hex('#f08a2a'), b = hex('#f4f0e6'), f = hex('#3a3c48'); R.linea(x, y, x + 2, y - 9, f); R.linea(x + 4, y, x + 2, y - 9, f); R.linea(x + 16, y, x + 18, y - 9, f); R.linea(x + 20, y, x + 18, y - 9, f); for (let i = 0; i <= 20; i++) for (let j = 0; j < 3; j++) R.pset(x + i, y - 9 + j, ((i + j) >> 2) & 1 ? n : b); for (let i = 0; i <= 20; i++) R.pset(x + i, y - 4, (i >> 2) & 1 ? b : n); }

// un cono de obra (x = su centro, y = el suelo)
function d_cono(R, x, y) { const n = hex('#f0702a'); R.rect(x - 3, y, x + 3, y, d_K); R.rect(x - 2, y - 2, x + 2, y - 1, n); R.rect(x - 1, y - 4, x + 1, y - 3, hex('#f4f0e6')); R.rect(x - 1, y - 6, x + 1, y - 5, n); R.pset(x, y - 7, n); }

// el camión del rodaje (88 × 34; x = su izquierda, y = las ruedas): cabina a la derecha, caja blanca con una franja y
// una estrella, el portón de atrás levantado con baúles y la rampa
function d_camionCine(R, x, y) {
  const bl = hex('#eceae4'), bs = hex('#c4c2bc'), bss = hex('#9a98a0'), az = hex('#3a5a8a');
  for (let i = -8; i < 92; i++) if (i % 3) d_os(R, x + i, y + 1, 0.4);
  R.rect(x - 1, y - 34, x + 61, y - 5, d_K); R.rect(x, y - 33, x + 60, y - 6, bl); R.rect(x, y - 33, x + 60, y - 32, hex('#ffffff')); R.rect(x, y - 10, x + 60, y - 6, bs); for (let i = x + 10; i < x + 60; i += 10) R.rect(i, y - 31, i, y - 7, bs);
  R.rect(x, y - 22, x + 60, y - 18, az); R.rect(x, y - 17, x + 60, y - 17, hex('#e8b830')); { const sx = x + 30, sy = y - 26; for (let k = -2; k <= 2; k++) { R.pset(sx + k, sy, hex('#e8b830')); R.pset(sx, sy + k, hex('#e8b830')); } R.pset(sx - 1, sy - 1, hex('#e8b830')); R.pset(sx + 1, sy - 1, hex('#e8b830')); R.pset(sx - 1, sy + 1, hex('#e8b830')); R.pset(sx + 1, sy + 1, hex('#e8b830')); }
  R.rect(x + 1, y - 30, x + 8, y - 7, hex('#2a2c34')); R.rect(x + 1, y - 30, x + 8, y - 27, bss); R.rect(x + 2, y - 14, x + 7, y - 8, hex('#8a6a3a')); R.rect(x + 2, y - 14, x + 7, y - 14, hex('#c8a060')); R.rect(x + 3, y - 20, x + 7, y - 15, hex('#4a4e5a')); R.pset(x + 5, y - 18, hex('#c8ccd4'));
  R.poligono([[x, y - 6], [x - 12, y], [x - 9, y + 1], [x + 2, y - 5]], bss); R.linea(x, y - 6, x - 12, y, hex('#5a5e6a'));
  R.rect(x + 61, y - 24, x + 83, y - 5, d_K); R.poligono([[x + 62, y - 6], [x + 62, y - 23], [x + 74, y - 23], [x + 80, y - 15], [x + 82, y - 14], [x + 82, y - 6]], bl); R.poligono([[x + 66, y - 15], [x + 66, y - 21], [x + 73, y - 21], [x + 77, y - 15]], hex('#9cc4e4')); R.rect(x + 62, y - 9, x + 82, y - 6, bs); R.rect(x + 81, y - 12, x + 82, y - 10, hex('#fff0a0')); R.rect(x + 83, y - 8, x + 85, y - 5, bss); R.rect(x + 64, y - 13, x + 65, y - 12, d_K);
  R.rect(x + 2, y - 5, x + 80, y - 4, hex('#3a3c48'));
  for (const wx of [14, 24, 72]) { R.disco(x + wx + 0.5, y - 3.5, 5, d_K); R.disco(x + wx + 0.5, y - 3.5, 4, hex('#2a2a32')); R.disco(x + wx + 0.5, y - 3.5, 1.8, hex('#c8ccd4')); }
}

// los coches de cada época: [tipo, color]
