  R.rect(130, 99, 190, 101, hex('#2a2c36')); R.rect(134, 102, 136, 122, hex('#2a2c36')); R.rect(184, 102, 186, 122, hex('#2a2c36')); R.rect(128, 108, 192, 110, hex('#3a3c48')); R.rect(140, 103, 178, 107, hex('#22242c')); R.rect(142, 104, 150, 106, hex('#4a4e5a')); R.pset(172, 105, hex('#e83a3a'));
  // el armario bajo de la izquierda: un ventilador, cajas de pizza y la unidad de cintas
