  for (let y = 116; y < 180; y++) for (let x = 0; x < 320; x++) { const g = h(x, y, 143), v = (y - 116) / 64, xj = (x - 160) / (0.55 + v * 0.9); let c = g < 0.12 ? hex('#161c32') : g > 0.92 ? hex('#262e4c') : hex('#1c2340'); const fy = Math.sqrt(v) * 5; if (Math.abs(fy - Math.round(fy)) < 0.035 / (0.2 + v) || Math.abs(xj / 36 - Math.round(xj / 36)) < 0.02) c = hex('#10142a'); px(x, y, c); }
  // a la derecha, la torre de discos con sus pilotos y una lámpara de lava
  R.rect(270, 84, 296, 122, d_K); R.rect(271, 85, 295, 121, hex('#2a3050')); R.rect(271, 85, 295, 86, hex('#4a5480')); for (let j = 0; j < 4; j++) { R.rect(273, 89 + j * 8, 293, 94 + j * 8, hex('#141830')); R.rect(274, 91 + j * 8, 284, 92 + j * 8, hex('#3a4268')); }
