  R.disco(153.5, 81.5, 4, hex('#a87a18')); R.disco(153.5, 81.5, 3, hex('#fbf8e8')); R.rect(150, 85, 157, 85, hex('#a87a18')); for (const cx of [134, 172]) { R.rect(cx, 78, cx, 85, hex('#c8a040')); R.rect(cx - 1, 85, cx + 1, 85, hex('#a87a18')); R.rect(cx, 74, cx, 77, hex('#f2f2ee')); }
