  // la ventana del decorado (lo de detrás lo pinta el fotograma) con sus cortinas
  R.rect(194, 60, 232, 112, hex('#efe6d0')); R.rect(196, 62, 230, 110, hex('#7ab4e0')); R.rect(194, 112, 232, 114, hex('#d8cfb8')); R.rect(194, 115, 232, 115, hex('#2a3e32'));
  // los apliques
