// 'plato', cámara 'camara' (inserto): las luces del fondo, los tambores, el contador, el piloto y la claqueta, con sus
// tres casillas (o.escena, o.plano, o.toma: de 0 a 99, cada cifra dentro de su casilla)
function d_camara(R, t, o = {}) {
  R.copiar(d_capa(R, 'ke-camara', () => d_camaraFija(R)));
  const f0 = hex('#2c2e36'), fL = hex('#7a7e8c');
  // las luces del fondo, desenfocadas, que tiemblan (lejos de la barra del año y de Atom)
  for (const [x, y, r, c, k] of [[196, 30, 7, '#f0c070', 0], [236, 26, 5, '#ffe8b0', 1], [18, 40, 6, '#f0c070', 2], [262, 60, 4, '#8ac8e8', 3], [56, 32, 4, '#ffe8b0', 4]]) { const rr = r + Math.sin(t * 2 + k * 2) * 0.8; for (let j = -r - 2; j <= r + 2; j++) for (let i = -r - 2; i <= r + 2; i++) { const d = Math.hypot(i, j); const fo = R.pget(x + i, y + j); if (d <= rr && (fo === hex('#1c1924') || fo === hex('#262230'))) if (d < rr - 2 || d_b4(x + i, y + j) < 0.6) d_os(R, x + i, y + j, d < rr - 2 ? 0.6 : 0.35, hex(c)); } }
  // los tambores del chasis giran, el contador de metros corre y el piloto de rodaje parpadea
  for (const cx of [101, 143]) { R.disco(cx, 42, 5, d_K); R.disco(cx, 42, 4, fL); for (let k = 0; k < 3; k++) { const a = t * 2.4 * (cx < 120 ? 1 : -1) + k * 2.094; R.linea(cx, 42, cx + Math.cos(a) * 10, 42 + Math.sin(a) * 10, hex('#3e404a')); R.pset(cx + Math.cos(a) * 3, 42 + Math.sin(a) * 3, d_K); } }
  R.numero(String(1000 + Math.floor(t * 6) % 9000), 94, 85, { color: hex('#7aff8a'), sombra: false });
  R.rect(158, 66, 162, 68, Math.sin(t * 4) > 0 ? hex('#ff4040') : hex('#5a1a1a'));
  // el brillo del cristal en la boca del parasol, y motas en la luz
  { const u = (t * 0.4) % 1; for (let k = 0; k < 9; k++) { const y = 66 + ((u * 50 + k * 3) % 50); R.pset(243, y, k < 3 ? hex('#cfe8ff') : hex('#5a86ac')); R.pset(242, y + 1, hex('#5a86ac')); } }
  motas(R, t, 180, 310, 60, 130, 10, hex('#f4e8b0'));
  // la claqueta: el brazo de rayas (o.clac 0 abierto … 1 cerrado), la pizarra con sus casillas y números
  const clac = Math.max(0, Math.min(1, o.clac ?? 0)), bx = 250, by = 112, ang = -(1 - clac) * 0.5 - (clac === 0 ? Math.sin(t * 1.5) * 0.03 : 0), bl = hex('#f2f2ee');
  R.rect(bx - 1, by + 5, bx + 48, by + 40, d_K); R.rect(bx, by + 6, bx + 47, by + 39, bl); R.rect(bx, by + 6, bx + 47, by + 6, hex('#ffffff')); R.rect(bx + 44, by + 7, bx + 47, by + 39, hex('#c8c8c0'));
  R.rect(bx, by + 16, bx + 47, by + 16, d_K); R.rect(bx, by + 28, bx + 47, by + 28, d_K); R.rect(bx + 16, by + 6, bx + 16, by + 28, d_K); R.rect(bx + 32, by + 6, bx + 32, by + 28, d_K);
  for (const [i, w] of [[2, 9], [19, 7], [35, 8]]) R.rect(bx + i, by + 9, bx + i + w, by + 10, hex('#8a8a92'));
  g_cifrasPizarra(R, o.escena ?? 35, bx + 8, by + 19, d_K); g_cifrasPizarra(R, o.plano ?? 4, bx + 24, by + 19, d_K); g_cifrasPizarra(R, o.toma ?? 1, bx + 40, by + 19, d_K);
  for (const [j, w] of [[32, 30], [36, 22]]) R.rect(bx + 3, by + j, bx + 3 + w, by + j, hex('#8a8a92'));
  for (let i = 0; i <= 47; i++) for (let j = 0; j < 5; j++) R.pset(bx + i, by + 1 + j, ((i + j) >> 2) & 1 ? d_K : bl);
  for (let i = 0; i <= 47; i++) for (let j = 0; j < 5; j++) { const x = bx + i * Math.cos(ang) + (j - 5) * Math.sin(-ang), y = by + i * Math.sin(ang) + (j - 5) * Math.cos(ang); R.pset(Math.round(x), Math.round(y), ((i - j + 40) >> 2) & 1 ? d_K : bl); }
  R.disco(bx + 1, by, 2, fL);
  return { inserto: true, suelo: null, objetivo: [246, 90], visor: [41, 70], chasis: [[101, 42], [143, 42]], claqueta: [bx, by, bx + 47, by + 39], bisagra: [bx, by], agarre: [bx + 44, by + 44], contador: [94, 85] };
}
