  // la pared crema con su grano, el techo de placas con el fluorescente, el friso de madera y la moqueta
  for (let y = 0; y < 180; y++) for (let x = 0; x < 320; x++) { const g = h(x, y, 171); let c;
    if (y < 10) { c = (x % 32 === 0 || y === 9) ? hex('#b8b4a4') : g < 0.2 ? hex('#d8d4c4') : hex('#e4e0d2'); }
    else if (y < 102) { c = g < 0.08 ? hex('#cdbd94') : g > 0.94 ? hex('#e4d6b0') : hex('#d8c8a0'); if (d_ruido(x, y, 30, 172) > 0.7 && d_b4(x, y) < 0.5) c = hex('#cdbd94'); if (y < 14) c = d_mez(c, d_K, (14 - y) * 0.05); }
    else if (y < 124) { const u = x % 14; c = y < 104 ? (y === 102 ? maL : maS) : y > 120 ? maS : u === 0 ? maS : u === 1 ? maL : g < 0.12 ? hex('#7e5830') : ma; if (y > 104 && y <= 120 && (y + Math.round(Math.sin(x * 0.3 + (x / 14 | 0)) * 2)) % 9 === 0 && u > 2) c = hex('#7e5830'); }
    else { c = g < 0.3 ? hex('#525c70') : g > 0.85 ? hex('#687490') : hex('#5c6680'); if (d_ruido(x, y * 2, 20, 173) > 0.68) c = d_mez(c, hex('#4a5266'), 0.5); if (y < 127) c = d_mez(c, d_K, y === 124 ? 0.4 : 0.2); }
    px(x, y, c); }
