  R.rect(6, 24, 54, 96, hex('#f2eee0')); R.rect(6, 24, 54, 24, hex('#ffffff')); R.rect(53, 25, 54, 96, hex('#c8c4b4')); R.rect(4, 96, 56, 98, hex('#f2eee0')); R.rect(4, 99, 56, 99, hex('#a89e84')); for (let y = 25; y < 97; y++) d_os(R, 55, y + 1, 0.2); for (let x = 5; x < 58; x++) d_os(R, x, 100, 0.25);
  // el tablero: corcho en 1994, pizarra blanca en 2016
  if (!hoy) { R.rect(62, 22, 238, 98, maS); R.rect(63, 23, 237, 97, ma); R.rect(63, 23, 237, 23, maL); for (let y = 26; y < 95; y++) for (let x = 66; x < 235; x++) { const g = h(x, y, 174); px(x, y, g < 0.14 ? hex('#a87838') : g > 0.86 ? hex('#d8b070') : g > 0.6 && h(x >> 1, y >> 1, 175) < 0.3 ? hex('#b88848') : hex('#c89a5a')); } for (let x = 66; x < 235; x++) { d_os(R, x, 26, 0.3); } for (let y = 26; y < 95; y++) d_os(R, 66, y, 0.3); }
  else { R.rect(62, 22, 238, 98, hex('#8a8e9c')); R.rect(63, 23, 237, 97, hex('#c8ccd4')); R.rect(63, 23, 237, 23, hex('#e8ecf2')); for (let y = 26; y < 95; y++) for (let x = 66; x < 235; x++) px(x, y, d_ruido(x, y, 16, 176) > 0.72 && d_b4(x, y) < 0.4 ? hex('#e6e8ec') : hex('#f6f6f2'));
    R.rect(70, 99, 230, 101, hex('#a8acb8')); R.rect(70, 101, 230, 101, hex('#6a6e7c')); for (const [x, c] of [[90, '#d8303a'], [102, '#3a6ab0'], [114, '#3aa85a'], [126, '#1e1a1e']]) { R.rect(x, 97, x + 8, 98, hex(c)); R.pset(x + 9, 97, hex('#f2f2ee')); } R.rect(190, 95, 204, 98, hex('#4a4e5a')); R.rect(190, 95, 204, 95, hex('#8a8e9c'));
    // la línea de los tres actos, flechas y garabatos de rotulador
    const az = hex('#3a6ab0'), ro = hex('#d8303a'); R.rect(72, 88, 228, 88, az); for (const x of [72, 112, 188, 228]) R.rect(x, 85, x, 91, az); R.linea(224, 85, 228, 88, az); R.linea(224, 91, 228, 88, az); for (let k = 0; k < 30; k++) px(92 + k, 84 - Math.round(Math.sin(k / 30 * 3.14) * 3), ro); }
  for (let x = 62; x < 240; x++) d_os(R, x, 99 + (hoy ? 3 : 0), 0.22); for (let y = 23; y < 99; y++) d_os(R, 239, y, 0.22);
  // a la derecha: el reloj, un cuadro, la balda con guiones y una copa, y el surtidor de agua
  R.disco(262, 62, 10, d_K); R.disco(262, 62, 9, hex('#f8f6ec')); for (let k = 0; k < 12; k++) px(262 + Math.cos(k * 0.5236) * 7.4, 62 + Math.sin(k * 0.5236) * 7.4, hex('#6a6a7a')); for (let k = 0; k < 12; k++) d_os(R, 264 + Math.cos(k * 0.26 + 0.3) * 10.5, 64 + Math.sin(k * 0.26 + 0.3) * 10.5, 0.25);
