  { const u = (t * 0.03) % 1, x = 6 + u * 52, y = 36 - u * 5; d_rc(R, x, y, x + 3, y, hex('#f2f2ee')); R.pset(x + 1, y - 1, hex('#c8ccd4')); for (let k = 1; k < 14; k++) if (k % 2) R.pset(x - k, y + k * 0.1, hex('#e8f0f8')); }
