//   ·· tele: el salón de familia de 1996, de tarde ··
// los dibujos animados de la tele, recortados a su pantalla: una selva de colores planos (nuestra) que pasa, con un dado
// con patas que corre y salta
function e_dibujos(R, t, [x0, y0, x1, y1]) {
  R.recorte([x0, y0, x1, y1]); const w = x1 - x0;
  e_r(R, x0, y0, x1, y1, (x, y) => y < y0 + 22 ? hex('#6ad0f0') : y < y0 + 30 ? hex('#3aa85a') : hex('#e8c040'));
  R.disco(x1 - 9, y0 + 7, 4, hex('#fff0a0'));
  for (let k = 0; k < 4; k++) { const x = x0 + (((k * 23 - t * 8) % (w + 30)) + w + 30) % (w + 30) - 12; R.poligono([[x, y0 + 26], [x + 8, y0 + 8], [x + 16, y0 + 26]], k % 2 ? hex('#2e7a42') : hex('#5cb060')); }
  for (let k = 0; k < 5; k++) { const x = x0 + (((k * 19 - t * 22) % (w + 30)) + w + 30) % (w + 30) - 12; e_r(R, x + 5, y0 + 14, x + 7, y0 + 31, hex('#7a4a2a')); R.disco(x + 6, y0 + 12, 6, hex('#1c9a4a')); R.disco(x + 3, y0 + 10, 3, hex('#8ae05a')); }
  for (let x = x0; x <= x1; x += 6) R.pset(x + Math.floor((t * 30) % 6), y0 + 34, hex('#c89a20'));
  const salto = Math.abs(Math.sin(t * 4)) * 7, dx = x0 + 20 + Math.round(Math.sin(t * 0.8) * 6), dy = Math.round(y0 + 23 - salto), pas = Math.floor(t * 8) % 2;
  e_r(R, dx - 1, dy - 1, dx + 8, dy + 8, C.k); e_r(R, dx, dy, dx + 7, dy + 7, hex('#ffffff')); for (const [i, j] of [[1, 1], [5, 5], [3, 3]]) { R.pset(dx + i, dy + j, hex('#c83a3a')); R.pset(dx + i + 1, dy + j, hex('#c83a3a')); } R.pset(dx + 6, dy + 2, C.k);
  R.linea(dx + 2, dy + 9, dx + 1 + pas * 2, dy + 11, C.k); R.linea(dx + 5, dy + 9, dx + 6 - pas * 2, dy + 11, C.k);
  for (let y = y0; y <= y1; y += 2) for (let x = x0; x <= x1; x++) if (((x + y + Math.floor(t * 20)) & 7) === 0) R.pset(x, y, e_mez(R.pget(x, y), C.k, 0.2));
  R.recorte(null);
}

