  for (let y = 58; y <= 86; y++) for (let x = 98; x <= 126; x++) { const d = Math.hypot(x - 112, (y - 76) * 1.2) / 18, g = 1 - d + 0.12 * Math.sin(t * 3); pset(x, y, g > 0.75 ? hex('#d8ffc0') : g > 0.45 + f_b4(x, y) * 0.2 ? hex('#7af09a') : g > 0.1 + f_b4(x, y) * 0.3 ? hex('#2eb86a') : f_C.h2); }
  for (const [x0, d] of [[97, -1], [127, 1]]) for (let k = 0; k < 6; k++) { rect(x0 + d * k, 58 + k, x0 + d * k, 86 - (k >> 1), k === 0 || k === 5 ? f_C.sillarD : k === 3 ? f_C.sillarD : hex('#6a84b8')); pset(x0 + d * k, 70 + (k >> 1), f_C.sillarD); }
  f_LIANAS_CALLE.forEach(([pts, a, m], k) => f_liana(R, pts, q(a), t, { mece: m, sem: k, flores: k % 2 === 0, hoja: k < 5 ? 1 : 0 }));
