function f_cabana(R, t, o = {}) {
  const { pset, rect } = R;
  R.copiar(f_capa(R, 'ca0', () => f_cabanaFijo(R)));
  // el humo de la estufa, la cortina de cuentas de la puerta y la hamaca que se mece
  for (let k = 0; k < 5; k++) { const u = (t * 0.25 + k / 5) % 1, x = Math.round(200 + Math.sin(u * 5 + k) * 3 + u * 8), y = Math.round(36 - u * 14); R.disco(x, y, 1 + u * 2, u > 0.6 ? hex('#5a8a70') : hex('#c8d8c0')); }
  for (let x = 152; x <= 170; x += 3) for (let y = 85; y < 106 + (x % 2) * 4; y += 2) pset(x + Math.round(Math.sin(t * 1.6 + x + y * 0.1) * (y - 85) / 22), y, [f_C.oro, f_C.rojo, hex('#58c8f0'), f_C.h5][(x + y) % 4]);
  { const m = Math.sin(t * 1.2) * 1.5; for (let x = 67; x <= 112; x++) { const u = (x - 67) / 45, y = Math.round(90 + Math.sin(u * Math.PI) * 12 + m * Math.sin(u * Math.PI)); if (u < 0.12 || u > 0.88) { pset(x, y, hex('#d8c8a0')); continue; } for (let k = 0; k < 4; k++) pset(x, y + k, k === 3 ? hex('#8a2a3c') : (x >> 2) % 2 ? hex('#f0e8d8') : f_C.rojo); pset(x, y - 1, hex('#d8c8a0')); } }
  // el farol colgado del alero (tiembla) con su luz sobre la madera, y la ropa tendida
  { const fl = Math.sin(t * 9) * 0.5 + Math.sin(t * 14) * 0.5, x = 224, y = 80; for (let j = -18; j <= 18; j++) for (let i = -18; i <= 18; i++) { const d = Math.hypot(i, j); if (d < 17 + fl && d > 4 && f_b4(x + i, y + j) > 0.44 + d * 0.032) pset(x + i, y + j, f_mez(R.pget(x + i, y + j), f_C.oroL, 0.5)); }
    rect(x, 70, x, 75, f_C.k); rect(x - 3, 75, x + 3, 76, f_C.k); rect(x - 2, 77, x + 2, 83, f_C.oroL); rect(x - 1, 78 + (fl > 0 ? 1 : 0), x + 1, 82, f_C.blanco); rect(x - 3, 77, x - 3, 83, f_C.k); rect(x + 3, 77, x + 3, 83, f_C.k); rect(x - 3, 84, x + 3, 85, f_C.k); }
  for (let x = 222; x <= 262; x++) { const u = (x - 222) / 40, y = Math.round(64 - u * 14 + Math.sin(u * Math.PI) * 5); pset(x, y, hex('#d8c8a0')); if (x === 234 || x === 246) { const m = Math.round(Math.sin(t * 2 + x) * 1); for (let k = 1; k < 8; k++) { pset(x + (k > 4 ? m : 0), y + k, x === 234 ? f_C.rojo : hex('#f0e8d8')); pset(x + 1 + (k > 4 ? m : 0), y + k, x === 234 ? hex('#8a2a3c') : hex('#c8c0b0')); pset(x + 2 + (k > 4 ? m : 0), y + k, x === 234 ? f_C.rojo : hex('#f0e8d8')); } } }
  // el tucán en el caballete, las lianas, las mariposas, las luciérnagas y un rayo de sol
  f_tucan(R, 124, 46, 1, t, { aleteo: (t % 8) > 7.2 });
  for (const [x, L, k] of [[36, 70, 0], [90, 26, 1], [236, 20, 2], [278, 80, 3], [300, 50, 4], [12, 96, 5]]) f_liana(R, [[x, 16], [x + (k % 2 ? 3 : -3), 16 + L * 0.5], [x, 16 + L]], 1, t, { mece: 3, sem: k + 11, flores: k % 2 === 0 });
  [[40, 130, f_C.oro], [280, 120, f_C.rosa], [90, 150, hex('#58c8f0')]].forEach(([x, y, c], k) => f_mariposa(R, x, y, t, c, k + 9));
  for (let k = 0; k < 16; k++) { const x = Math.round(h(k, 7, 110) * 320 + Math.sin(t * 0.6 + k) * 8), y = Math.round(40 + h(k, 8, 110) * 120 + Math.cos(t * 0.5 + k * 2) * 5); if (Math.sin(t * 2 + k * 1.9) > 0.2) { pset(x, y, f_C.oroL); if (k % 3 === 0) pset(x + 1, y, f_C.h7); } }
  for (const [x0, w, k] of [[30, 12, 0], [270, 9, 1]]) { const br = 0.2 + 0.06 * Math.sin(t * 0.9 + k * 2); for (let y = 20; y < 160; y++) { const xa = x0 + (y - 20) * 0.3; for (let x = Math.round(xa); x < xa + w; x++) if (((x + y) & 1) && f_b4(x, y) < br * (1 - (y - 20) / 180)) pset(x, y, hex('#f8f0b0')); } }
  return {};
}

