  { const [cx, cy] = G_MES.taza; for (let j = -15; j <= 18; j++) for (let i = -15; i <= 19; i++) if (Math.hypot(i - 3, j - 3) < 15.5 && Math.hypot(i, j) > 15) g_tinta(R, cx + i, cy + j, K.k, 0.35);
    disco(cx, cy, 16, K.k); disco(cx, cy, 15, K.frisoL); disco(cx, cy, 13, K.friso); disco(cx, cy, 12, K.frisoL); rect(cx + 9, cy - 3, cx + 17, cy + 3, K.k); rect(cx + 10, cy - 2, cx + 16, cy + 2, K.blanco); rect(cx + 11, cy - 1, cx + 14, cy + 1, K.frisoL);
    disco(cx, cy, 10, K.k); disco(cx, cy, 9, K.blanco); disco(cx, cy, 7, J.te); for (let j = -7; j <= 7; j++) for (let i = -7; i <= 7; i++) { const d = Math.hypot(i, j); if (d < 7.5 && d > 5.6 && i + j > 2) pset(cx + i, cy + j, hex('#96582a')); } pset(cx - 6, cy - 6, K.marcoS); pset(cx - 7, cy - 5, K.marcoS); }
  // el folleto de instrucciones, doblado (rayas, un dado, sin letras)
  { const x = 22, y = 136; for (let j = 0; j <= 34; j++) for (let i = 0; i <= 44; i++) if (i > 41 || j > 31) g_tinta(R, x + i + 2, y + j + 2, K.k, 0.3);
    rect(x, y, x + 42, y + 32, K.k); rect(x + 1, y + 1, x + 41, y + 31, J.carton); rect(x + 1, y + 1, x + 41, y + 1, J.cartonL); rect(x + 21, y + 1, x + 21, y + 31, J.cartonS); rect(x + 22, y + 1, x + 22, y + 31, J.cartonL); rect(x + 1, y + 31, x + 41, y + 31, J.cartonD);
    rect(x + 5, y + 5, x + 13, y + 13, J.tinta); rect(x + 6, y + 6, x + 12, y + 12, J.cartonL); for (const [i, j] of [[7, 7], [11, 7], [9, 9], [7, 11], [11, 11]]) pset(x + i, y + j, J.tinta);
    for (let r = 0; r < 5; r++) { rect(x + (r < 3 ? 16 : 5), y + 6 + r * 5 - (r < 3 ? 0 : 0), x + 19, y + 6 + r * 5, J.tintaL); rect(x + 25, y + 6 + r * 5, x + 38 - (r * 5) % 7, y + 6 + r * 5, J.tintaL); } linea(x + 25, y + 4, x + 30, y + 4, K.rojoS); }
  // la hoja de puntos: palotes de cinco en cinco, en dos columnas, y el lápiz corto de apuntar
  { const [ax, ay, bx, by] = G_MES.hojaPuntos; for (let j = ay; j <= by + 2; j++) for (let i = ax; i <= bx + 2; i++) if (i > bx || j > by) g_tinta(R, i, j, K.k, 0.3);
    rect(ax, ay, bx, by, K.k); rect(ax + 1, ay + 1, bx - 1, by - 1, K.blanco); for (let y = ay + 7; y < by - 2; y += 7) rect(ax + 3, y, bx - 3, y, K.cielo4); rect(ax + 29, ay + 2, ax + 29, by - 2, K.rosa);
    for (const [gx, gy, n] of [[ax + 5, ay + 10, 5], [ax + 17, ay + 10, 2], [ax + 5, ay + 19, 4], [ax + 33, ay + 10, 5], [ax + 45, ay + 10, 5], [ax + 33, ay + 19, 3], [ax + 5, ay + 28, 1]]) { for (let q = 0; q < Math.min(4, n); q++) linea(gx + q * 2, gy, gx + q * 2, gy + 5, J.tinta); if (n === 5) linea(gx - 1, gy + 5, gx + 7, gy, J.tinta); }
    disco(ax + 8, ay + 5, 1, K.rojo); disco(ax + 36, ay + 5, 1, K.azul); }
  // dos fichas fuera, esperando (vistas desde arriba)
  for (const [x, y, c, cs, cl] of [[82, 158, K.verde, K.verdeS, K.verdeL], [70, 150, K.amarillo, K.oroS, K.oroL]]) { g_tinta(R, x + 5, y + 6, K.k, 0.4); g_tinta(R, x + 6, y + 5, K.k, 0.4); disco(x, y, 5, K.k); disco(x, y, 4, c); disco(x, y, 2, cs); disco(x - 1, y - 1, 1, cl); pset(x - 2, y - 3, K.blanco); }
