  R.poligono([[X(-12), Y(9)], [X(8), Y(15)], [X(8), Y(13)], [X(-12), Y(7)]], J.tinta); if (e > 1) { R.poligono([[X(-11), Y(8.6)], [X(7), Y(14)], [X(7), Y(13.6)], [X(-11), Y(8.2)]], J.cartonL); R.poligono([[X(-7), Y(10.6)], [X(3), Y(13.6)], [X(3), Y(13)], [X(-7), Y(10)]], K.blanco); }
  T(-8, 8, -11, 0); T(-8, 8, -5, 0); T(5, 12, 2, 0); T(5, 12, 8, 0); T(-10, 3, 7, 3, J.tintaL, 1); T(-12, 0, -4, 0); T(1, 0, 9, 0);
  if (e > 1) { for (let i = 0; i < 4; i++) T(-6 + i * 2.4, 11.4 + i * 0.72, -4.6 + i * 2.4, 11.8 + i * 0.72, J.grafM, 1); }
  // el flexo: pinza, dos brazos y la pantalla
  T(9, 14.5, 12, 21, J.tinta); T(12, 21, 7, 24, J.tinta); R.disco(X(12), Y(21), e > 1 ? 2 : 1, J.tinta);
  R.poligono([[X(3), Y(20)], [X(9), Y(22)], [X(8), Y(25)], [X(5), Y(24.5)]], J.tinta); if (e > 1) { R.poligono([[X(4), Y(20.8)], [X(8.4), Y(22.3)], [X(7.6), Y(24.3)], [X(5.3), Y(23.8)]], K.rojo); T(4.6, 21.4, 5.6, 23.4, K.rosa, 1); T(3.2, 19.8, 8.6, 21.6, K.luz, 1); }
  else R.pset(X(6), Y(22), K.rojo);
