  g_rutaLinea().p.forEach(([x, y], i) => { if (i % 4 < 2) pset(Math.round(x), Math.round(y), J.kraftD); });
  for (let x = x0 + 8; x < x1 - 4; x += 8) { pset(x, y1 - 2, J.kraftD); if ((x - x0) % 32 === 0) { pset(x, y1 - 3, J.kraftD); pset(x, y1 - 4, J.kraftD); } }
