  g_chincheta(R, x0 + 4, y1 - 4, K.azul); g_chincheta(R, (x0 + x1) >> 1, y0 + 3, K.rojo); g_chincheta(R, x1 - 12, y1 - 4, K.verde);
  // las tarjetas de la derecha: una hoja de selva dibujada y un interrogante
  { const [a, b, c, d] = G.tarjetas[0]; rect(a + 2, b + 2, c + 2, d + 2, K.paredS); rect(a, b, c, d, K.k); rect(a + 1, b + 1, c - 1, d - 1, K.blanco); rect(a + 1, d - 1, c - 1, d - 1, K.papelS); for (let j = 0; j < 15; j++) { const w = Math.round(Math.sin(j / 14 * Math.PI) * 6); rect(a + 13 - w, b + 5 + j, a + 13 + w, b + 5 + j, j % 4 === 3 ? K.hojaS : K.hoja); pset(a + 13, b + 5 + j, K.hojaD); pset(a + 13 - w, b + 5 + j, K.hojaS); } linea(a + 13, b + 20, a + 13, b + 22, K.hojaD); g_chincheta(R, a + 13, b + 2, K.amarillo); }
  { const [a, b, c, d] = G.tarjetas[1]; rect(a + 2, b + 2, c + 2, d + 2, K.paredS); rect(a, b, c, d, K.k); rect(a + 1, b + 1, c - 1, d - 1, K.luz); rect(a + 1, d - 1, c - 1, d - 1, K.sol); R.icono('?', a + 10, b + 7, K.rojoS, K.sol, 1); for (let r = 0; r < 3; r++) rect(a + 4, b + 16 + r * 2, c - 4 - r * 4, b + 16 + r * 2, K.papelD); g_chincheta(R, a + 13, b + 2, K.rojo); }
  // el banco bajo de la izquierda: rollos de papel, un bote con pinceles, una caja de juego
  rect(18, 138, 96, 152, K.k); rect(19, 139, 95, 142, K.nogalL); rect(19, 139, 95, 139, K.nogalB); rect(19, 143, 95, 143, K.nogalS); rect(22, 144, 25, 152, K.nogal); rect(89, 144, 92, 152, K.nogal); rect(26, 147, 88, 148, K.nogalS); for (let x = 20; x < 95; x += 5) if (h(x, 3, 66) < 0.5) pset(x, 141, K.nogal);
  for (const [x, a, c] of [[26, 22, J.kraft], [32, 28, K.papel], [38, 18, J.kraftL]]) { rect(x, 138 - a, x + 5, 138, K.k); rect(x + 1, 139 - a, x + 4, 137, c); rect(x + 4, 139 - a, x + 4, 137, g_mez(c, K.k, 0.25)); rect(x + 1, 139 - a, x + 4, 139 - a, K.blanco); disco(x + 2, 139 - a, 1, g_mez(c, K.k, 0.4)); }
  rect(50, 128, 58, 138, K.k); rect(51, 129, 57, 137, K.barro); rect(51, 129, 57, 130, K.barroL); rect(56, 131, 57, 137, K.barroS); for (const [x, a, c] of [[52, 9, K.rojo], [54, 12, K.azul], [56, 8, K.amarillo]]) { linea(x, 128, x, 128 - a, K.nogalL); pset(x, 127 - a, c); pset(x, 128 - a, c); }
