  for (let y = 155; y <= 179; y++) { const u = (y - 155) / 24, xa = Math.round(150 - u * 40), xb = Math.round(206 - u * 30); for (let x = xa; x <= xb; x++) { const v = (x - xa) / (xb - xa); if (Math.abs(v - 0.5) < 0.03 || Math.abs(u - 0.45) < 0.04) continue; g_tinta(R, x, y, K.solL, 0.4); } }
  { const [px, py] = G.planta; for (let k = 0; k < 9; k++) { const a = -2.7 + k * 0.56, m = Math.sin(t * 1.1 + k) * 1.2, x = Math.round(px + Math.cos(a) * (8 + k % 3 * 3) + m), y = Math.round(py - 30 + Math.sin(a) * 9 + (k % 2) * 4); R.linea(px, py - 24 + (k % 3) * 3, x, y, K.hojaS); R.disco(x, y, 3, K.hojaD); R.disco(x, y, 2, k % 3 ? K.hoja : K.hojaL); R.pset(x - 1, y - 1, K.hojaB); } }
  // la línea a tinta, hasta donde llega
  for (let i = 0; i <= n; i++) { const x = Math.round(p[i][0]), y = Math.round(p[i][1]); R.pset(x, y, J.tinta); R.pset(x + 1, y, J.tinta); R.pset(x, y + 1, J.tinta); R.pset(x + 1, y + 1, J.tintaL); }
  // los nudos: su círculo a lápiz y, cuando llega la línea, la pieza, la chincheta y el año
  G.nudos.forEach(([x, y], k) => { const yy = Math.round(p[Math.round(en[k] * p.length)][1]), llega = k === 0 || tr >= en[k], pop = k === 0 ? 1 : g_cl((tr - en[k]) / 0.03), dy = Math.round((1 - pop) * 3);
    if (!llega) { for (let a = 0; a < 12; a++) if (a % 2) R.pset(x + Math.round(Math.cos(a * 0.5236) * 5), yy + Math.round(Math.sin(a * 0.5236) * 5), J.kraftD); return; }
    if (k === 0) g_iconoMesa(R, x, yy - 5, 1, 1, t); else if (k === 1 && P.tablero) P.tablero(R, x, yy - 5 + dy, { t }); else if (k === 2 && P.cartucho) P.cartucho(R, x, yy - 6 + dy); else if (k === 3 && P.consola) P.consola(R, x, yy - 6 + dy, { encendida: Math.sin(t * 3) > -0.3 });
    R.disco(x, yy, 4, K.k); R.disco(x, yy, 3, J.kraftL); R.disco(x, yy, 2, [K.oro, K.rojo, K.azul, K.verde][k]); R.pset(x - 1, yy - 1, K.blanco);
    if (G.años[k] && pop >= 1) R.numero(G.años[k], x, yy + 16, { centro: true, color: J.tinta, sombra: false }); });
  // la punta que dibuja o, ya cerrado el bucle, la flecha que toca el flexo y la chispa que da la vuelta
  if (tr < 1 && n > 0) { const [x, y] = p[n]; g_trazo(R, x + 1, y - 1, x + 6, y - 6, K.k, 3); g_trazo(R, x + 2, y - 2, x + 6, y - 6, K.amarillo, 1); R.pset(Math.round(x), Math.round(y), J.graf); R.pset(Math.round(x) + 1, Math.round(y) - 1, K.pared); }
  else if (tr >= 1) { const [fx, fy] = G.flecha; R.poligono([[fx, fy - 1], [fx - 4, fy + 5], [fx + 5, fy + 5]], J.tinta); R.pset(fx, fy, J.tinta);
    const q = Math.floor(((t * 0.22) % 1) * p.length), [sx, sy] = p[q]; R.disco(Math.round(sx), Math.round(sy), 2, K.oroL); R.pset(Math.round(sx), Math.round(sy), K.blanco); for (let b = 1; b < 4; b++) { const [bx, by] = p[(q - b * 3 + p.length) % p.length]; R.pset(Math.round(bx), Math.round(by), K.oro); }
    const r = 6 + Math.round(((t * 0.9) % 1) * 5); for (let a = 0; a < 16; a++) if ((a + Math.floor(t * 6)) % 2) R.pset(G.nudos[0][0] + Math.round(Math.cos(a * 0.3927) * r), G.nudos[0][1] + Math.round(Math.sin(a * 0.3927) * r), K.oro); }
