  for (let y = 0; y <= 56; y++) for (let x = 0; x < 320; x++) if ((y < 24 && x < 184) || (x > 256 && y < 56)) pset(x, y, h(x >> 2, y, 61) < 0.05 ? J.kraftS : J.kraft);
  const { sale, vuelve } = g_rutaBucle(); [...sale, ...vuelve].forEach(([x, y], i) => { if (i % 6 < 3) { pset(Math.round(x), Math.round(y), J.kraftD); pset(Math.round(x), Math.round(y) + 1, J.kraftS); } });
  // la mancha de la taza
  for (let a = 0; a < 6.283; a += 0.02) { const r = 17 + Math.sin(a * 3) * 0.6; if (h(Math.round(a * 20), 1, 69) < 0.8) pset(Math.round(204 + Math.cos(a) * r), Math.round(60 + Math.sin(a) * r * 0.95), J.kraftS); if (h(Math.round(a * 20), 2, 69) < 0.4) pset(Math.round(204 + Math.cos(a) * (r - 1)), Math.round(60 + Math.sin(a) * (r - 1) * 0.95), J.kraftD); }
  // garabatos a lápiz: estrellas, un dado, una espiral, flechitas y cotas
  for (const [x, y] of [[172, 126], [300, 122], [40, 60], [230, 100]]) { linea(x - 3, y, x + 3, y, J.grafM); linea(x, y - 3, x, y + 3, J.grafM); pset(x - 2, y - 2, J.grafL); pset(x + 2, y + 2, J.grafL); pset(x + 2, y - 2, J.grafL); pset(x - 2, y + 2, J.grafL); }
  rect(26, 84, 38, 96, J.grafM); rect(27, 85, 37, 95, J.kraft); for (const [i, j] of [[29, 87], [35, 87], [32, 90], [29, 93], [35, 93]]) rect(i, j, i + 1, j + 1, J.grafM);
