  if (r > 8) { const m = Math.round(r * 0.42); R.linea(x - m, y - m, x + m, y - m, J.gemaL); R.linea(x - m, y - m, x - m, y + m, J.gemaL); R.linea(x + m, y - m, x + m, y + m, J.gemaD); R.linea(x - m, y + m, x + m, y + m, J.gemaD); for (const [sx, sy] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) R.linea(x + sx * m, y + sy * m, x + sx * Math.round(r * 0.7), y + sy * Math.round(r * 0.7), sx + sy < 0 ? J.gemaL : J.gemaD); }
