  for (let y = 26; y <= 121; y++) for (let x = 50; x <= 276; x++) if ((x < 58 || x > 262) && g_b4(x, y) < 0.5) g_tinta(R, x + 8, y, K.k, 0.25);
  rect(57, 22, 263, 151, K.k); for (let y = 23; y <= 150; y++) for (let x = 58; x <= 262; x++) { const v = y + Math.sin(x * 0.05) * 2, f = ((v % 8) + 8) % 8; pset(x, y, f < 1 ? J.tabS : f > 7 ? J.tabL : h(x >> 2, y, 92) < 0.06 ? J.tabS : J.tab); }
  rect(58, 23, 262, 23, J.tabB); rect(58, 23, 58, 150, J.tabL); rect(262, 22, 262, 150, J.tabD);
  for (const [ex, dx] of [[58, 1], [262, -1]]) for (const [ey, dy] of [[23, 1], [150, -1]]) for (let i = 0; i < 9; i++) for (let j = 0; j < 9 - i; j++) pset(ex + dx * i, ey + dy * j, i + j > 6 ? K.oroS : i + j < 2 ? K.oroL : K.oro);
