  { const pp = Math.sin(t * 9) > 0.96 ? 0.1 : 0.16; for (let y = 26; y <= 148; y += 1) for (let x = 72; x <= 150 - (y - 26) * 0.5; x++) if (g_b4(x, y) < pp * (1 - (x - 72) / 90)) g_tinta(R, x, y, K.blanco, 0.5); }
