  rect(0, 160, 319, 161, J.cartonD); rect(0, 162, 319, 162, K.k); g_tablero(R, 163, 179, 160, 190); for (let y = 163; y <= 167; y++) for (let x = 0; x < 320; x++) if (g_b4(x, y) < 0.8 - (y - 163) * 0.15) g_tinta(R, x, y, K.k, 0.35);
