  for (const [bx, w] of [[20, 60], [96, 40], [150, 30]]) rect(bx, 70, bx + w, 71, J.cartonD); for (const [bx, w] of [[20, 44], [70, 70]]) rect(bx, 76, bx + w, 77, J.cartonD);
  for (const [x, y] of [[196, 36], [60, 40], [128, 34]]) { linea(x - 3, y, x + 3, y, J.cartonD); linea(x, y - 3, x, y + 3, J.cartonD); }
