  const tiembla = e > 0.6 ? (e - 0.6) / 0.4 : 0, ox = (1 - tiembla) * mi * 5.5 * (1 - e * 0.6) + tiembla * (Math.sin(t * 13) > 0 ? 3 : -3) + tiembla * Math.sin(t * 47) * 1.2, oy = 4.5 - Math.abs(mi) * 1.5 * (1 - e) + tiembla * Math.sin(t * 39) * 1 + ((t % 1.7) < 0.18 ? 1 : 0);
