    for (const [xa, s] of [[a - 8, 1], [c + 8, -1]]) for (let y = b - 6; y <= d + 14; y++) { const w = y < b + 34 ? 12 - (y - b) * 0.12 : 5 + (y - b - 34) * 0.14; for (let i = 0; i <= w; i++) { const x = xa + i * s, f = Math.sin(i * 1.3 + y * 0.05); pset(x, y, i === 0 || i >= w - 1 ? T[4] : f > 0.5 ? T[1] : f < -0.4 ? T[3] : T[2]); } if (Math.abs(y - b - 34) < 2) for (let i = 0; i <= 6; i++) pset(xa + i * s, y, T[4]); }
