  { const a = x0 + 128, b = y0 + 12; rect(a, b, a + 34, b + 26, T[4]); rect(a + 2, b + 2, a + 32, b + 24, T[1]); rect(a + 5, b + 5, a + 29, b + 21, T[0]); for (let x = a + 5; x <= a + 29; x++) for (let y = b + 15; y <= b + 21; y++) if (g_raya(x, y, 0.55)) pset(x, y, T[2]); R.poligono([[a + 17, b + 7], [a + 24, b + 15], [a + 17, b + 15]], T[3]); linea(a + 16, b + 6, a + 16, b + 16, T[4]); rect(a + 11, b + 16, a + 24, b + 17, T[4]); linea(a + 17, b - 5, a + 10, b, T[3]); linea(a + 17, b - 5, a + 24, b, T[3]); }
  { const cx = x0 + 208, cy = y0 + 20; disco(cx, cy, 10, T[4]); disco(cx, cy, 8, T[0]); for (let q = 0; q < 12; q++) pset(cx + Math.round(Math.sin(q * 0.5236) * 6), cy - Math.round(Math.cos(q * 0.5236) * 6), T[3]); linea(cx, cy, cx + 3, cy - 3, T[4]); linea(cx, cy, cx - 1, cy + 5, T[4]); }
