  for (let k = 0; k < 3; k++) { const u = (t * 0.4 + k / 3) % 1, x = G.mesita[0] - 4 + Math.round(Math.sin(u * 6 + k * 2) * 2), y = G.mesita[1] - 7 - Math.round(u * 12); if (g_b4(x, y) < 1 - u) { R.pset(x, y, K.blanco); if (u < 0.5) R.pset(x, y - 1, Q.tablaL); } }
  // los destellos de las medallas, por turnos, y el polvo en la luz de la ventana
  { const n = Math.floor(t * 0.5) % 2, [a, b, c, d] = G.medallas[n]; g_destello(R, ((a + c) >> 1) - 2, d - 13, ((t * 0.5) % 1) * 1.6, K.blanco); }
