  for (let y = 0; y <= hy; y++) for (let x = 0; x <= hx; x++) pset(x, y, x === hx || y === hy ? J.hojaD : !(y < 24 && x < 184) && h(x >> 1, y >> 1, 99) < 0.05 ? J.hojaS : J.hoja);
