  const W = (u) => { const q = (u + L) / (2 * L); return q <= 0 || q >= 1 ? -1 : 30 * Math.sin(Math.PI * q) ** 0.75 * (0.75 + 0.25 * q) - (Math.abs(((u + L) % 20) - 10) < 2.2 ? 5 * Math.sin(Math.PI * q) : 0); };
  for (let y = cy - 70; y <= cy + 66; y++) for (let x = cx - 66; x <= cx + 70; x++) { if (x > G_ESQ.filete[0] - 4 || y > G_ESQ.filete[1] - 4 || y < 22) continue; const dx = x - cx, dy = y - cy, u = dx * sa - dy * ca, v = dx * ca + dy * sa, w = W(u); if (w < 0 || Math.abs(v) > w + 1) continue;
    const borde = Math.abs(v) > w - 0.6, vena = Math.abs((((u + L) + Math.abs(v) * 0.8) % 20) - 10) < 0.8 && Math.abs(v) > 2;
    R.pset(x, y, borde ? T[4] : Math.abs(v) < 1.3 ? T[4] : vena ? T[3] : v > 0 ? (g_raya(x, y, 0.75) ? T[3] : T[2]) : g_raya(x, y, 0.35, 1) ? T[2] : T[1]); }
