    if (nd > 0) { const e = 2.4; R.pset(G.perro[0] + Math.round(8.9 * e), G.perro[1] + Math.round(-13 * e), K.blanco); R.rect(G.perro[0] + Math.round(14.4 * e), G.perro[1] + Math.round(-11 * e), G.perro[0] + Math.round(15 * e), G.perro[1] + Math.round(-10.2 * e), T[4]); }
